COLLNT("muwattaansar",{"418":["§خلاصۃ الباب","اس باب میں تین روایات ہیں، ایک موقوف ہے جو سنداً ضعیف ہے اور دو مقطوع ہیں جن میں سے ایک صحیح اور ایک ضعیف ہے۔"],"419":["§خلاصۃ الباب","اس باب میں ایک مقطوع روایت (اثر تابعی) ہے جو سنداً صحیح ثابت ہے، نیز امام مالک رحمہ اللہ کے تین فتاویٰ جات بھی اس باب میں مذکور ہیں۔","..... ’’سائبہ‘‘ سے مراد وہ غلام یا لونڈی ہے جسے آزاد کرتے وقت کہا جائے کہ تیری ولاء میں کسی کا حق نہیں ہے۔"],"420":["§کتاب کا تعارف","اس کتاب میں تیرہ ابواب اور سات روایات ہیں، جن میں سے دو موقوف (آثار صحابہ) اور پانچ مقطوع (آثار تابعین) ہیں، ان میں سے تین روایات صحیح اور چار ضعیف ہیں، چنانچہ دو موقوف روایات میں سے ایک صحیح اور ایک ضعیف ہے اور پانچ مقطوع روایات میں سے دو صحیح اور تین ضعیف ہیں، یاد رہے کہ اس کتاب کے آٹھ ابواب میں کوئی روایت نہیں ہے، وہ امام مالک رحمہ اللہ کے فتاویٰ پر مشتمل ہیں، نیز اس کتاب میں کوئی مرفوع روایت بھی مذکور نہیں ہے، اس میں امام مالک رحمہ اللہ کے باسٹھ (۶۲) فتاویٰ جات مذکور ہیں۔","..... جس غلام سے مخصوص مدت میں مخصوص معاوضے کے بدلے آزادی کا معاہدہ طے پا جائے اسے ’’مکاتب غلام‘‘ کہتے ہیں۔ یہ لفظ ’’کتابت‘‘ سے ماخوذ ہے، کیونکہ عام طور پر یہ معاہدہ لکھ لیا جاتا تھا۔ اس معاہدے کو ’’مکاتبت‘‘ (عہد کتابت، عقد کتابت) معاہدہ کرنے والے آقا کو ’’مکاتب‘‘ (تاء کے نیچے زیر کے ساتھ) اور ایسے غلام کو ’’مکاتب‘‘ (تاء کے زبر کے ساتھ) اور آزادی کے لیے طے شدہ معاوضے کو ’’بدل کتابت‘‘ یا ’’زر کتابت‘‘ کہتے ہیں۔ بہر حال یہ خاص غلام شمار ہوتے ہیں۔ عام غلام کو ’’عبد‘‘ یا کبھی کبھار ’’خادم‘‘ یا ’’غلام‘‘ ہی کہتے ہیں اور ان کی آزادی چونکہ کسی معاوضے کے بغیر ہوتی ہے اس لیے عموماً اس کے لیے ’’عتق‘‘ کا لفظ بولتے ہیں، مکاتب غلاموں کا تذکرہ قرآن مجید میں یوں مذکور ہے، ارشاد الٰہی ہے:","﴿ وَالَّذِينَ يَبْتَغُونَ الْكِتَابَ مِمَّا مَلَكَتْ أَيْمَانُكُمْ فَكَاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًا وَآتُوهُمْ مِّن مَّالِ اللَّهِ الَّذِي آتَاكُمْ ﴾ [النور: ۳۳]","’’اور وہ (لونڈیاں اور غلام) کہ تمھارے دائیں ہاتھ جن کے مالک ہیں (ان میں سے جو) مکاتبت کرنا چاہیں، اگر تمھیں ان میں کوئی بھلائی معلوم ہو تو تم ان سے مکاتبت کرو اور تم انھیں اللہ کے اس مال میں سے دو جو اس نے تمھیں عطا کیا ہے۔‘‘","احادیث میں سیدہ بریرہ رضی اللہ عنہا والی روایت مکاتبت کے حوالے سے بہت مشہور ہے۔","§خلاصۃ الباب","اس باب میں تین روایات ہیں، ایک موقوف ہے جس کی سند صحیح ہے اور دو مقطوع ہیں جن میں سے ایک سند صحیح اور ایک ضعیف ہے، نیز امام مالک رحمہ اللہ کے دس فتاویٰ جات بھی اس میں مذکور ہیں۔"],"421":["§خلاصۃ الباب","اس باب میں کوئی روایت نہیں ہے، البتہ امام مالک رحمہ اللہ کے تین فتاوی جات مذکور ہیں۔","قَالَ مَالِكٌ : الأَمْرُ الْمُجْتَمَعُ عَلَيْهِ عِنْدَنَا : أَنَّ الْعَبِيدَ إِذَا كُوتِبُوا جَمِيعاً كِتَابَةً وَاحِدَةً ، فَإِنَّ بَعْضَهُمْ حُمَلَاءُ عَنْ بَعْضٍ ، وَإِنَّهُ لاَ يُوضَعُ عَنْهُمْ لِمَوْتِ أَحَدِهِمْ شَيْءٌ، وَإِنْ قَالَ أَحَدُهُمْ : قَدْ عَجَزْتُ. وَأَلْقَى بِيَدَيْهِ ، فَإِنَّ لأَصْحَابِهِ أَنْ يَسْتَعْمِلُوهُ فِيمَا يُطِيقُ مِنَ الْعَمَلِ، وَيَتَعَاوَنُونَ بِذَلِكَ فِي كِتَابَتِهِمْ حَتَّى يَعْتِقَ بِعِتْقِهِمْ إِنْ عَتَقُوا، وَيَرِقَّ بِرِقِّهِمْ إِنْ رَقُّوا.","امام مالک رحمہ اللہ نے فرمایا: ہمارے ہاں اس حکم پر اجماع ہے کہ بے شک جب کئی غلاموں سے اکٹھی مکاتبت کی گئی ہو) تو بلاشبہ ان میں سے بعض بعض کے ضامن ہوں گے اور ان میں سے کسی کے مرنے کی وجہ سے ان سے کچھ بھی کم نہ کیا جائے گا، پھر اگر ان میں سے کوئی یہ کہے کہ میں تو عاجز آچکا ہوں اور اپنے ہاتھ (پاؤں) چھوڑ بیٹھے تو بلاشبہ اس کے ساتھیوں کے لیے جائز ہے کہ اس سے اتنا کام کرواتے رہیں جس کی وہ طاقت رکھتا ہو اور وہ اس (سے کرائی گئی مزدوری) کے ساتھ اپنے بدل کتابت میں تعاون حاصل کر لیں، یہاں تک کہ اگر وہ (باقی) سب آزاد ہوں گے تو ان کی آزادی کے ساتھ ہی یہ (عاجز آنے والا) بھی آزاد ہو جائے گا اور اگر وہ سب (عاجز آکر) غلام ہی رہے تو ان کی غلامی کے ساتھ یہ بھی غلام ہی رہے گا۔","قَالَ مَالِكٌ: الْأَمْرُ الْمُجْتَمَعُ عَلَيْهِ عِنْدَنَا: أَنَّ الْعَبْدَ إِذَا كَاتَبَهُ سَيِّدُهُ، لَمْ يَنْبَغِ لِسَيِّدِهِ أَنْ يَتَحَمَّلَ لَهُ بِكِتَابَةِ عَبْدِهِ أَحَدٌ إِنْ مَاتَ الْعَبْدُ أَوْ عَجَزَ، وَلَيْسَ هَذَا مِنْ سُنَّةِ الْمُسْلِمِينَ، وَذَلِكَ أَنَّهُ إِنْ تَحَمَّلَ رَجُلٌ لِسَيِّدِ الْمُكَاتَبِ بِمَا عَلَيْهِ مِنْ كِتَابَتِهِ، ثُمَّ اتَّبَعَ ذَلِكَ سَيِّدُ الْمُكَاتَبِ قِبَلَ الَّذِي تَحَمَّلَ لَهُ أَخَذَ مَالَهُ بَاطِلاً، لَا هُوَ ابْتَاعَ الْمُكَاتَبَ، فَيَكُونَ مَا أُخِذَ مِنْهُ مِنْ ثَمَنِ شَيْءٍ هُوَ لَهُ، وَلَا الْمُكَاتَبُ عَتَقَ فَيَكُونَ فِي ثَمَنِ حُرْمَةٍ ثَبَتَتْ لَهُ، فَإِنْ عَجَزَ الْمُكَاتَبُ رَجَعَ إِلَى سَيِّدِهِ، وَكَانَ عَبْداً مَمْلُوكاً لَهُ، وَذَلِكَ أَنَّ الْكِتَابَةَ لَيْسَتْ بِدَيْنٍ ثَابِتٍ يُتَحَمَّلُ لِسَيِّدِ الْمُكَاتَبِ بِهَا، إِنَّمَا هِيَ شَيْءٌ إِنْ أَدَّاهُ الْمُكَاتَبُ عَتَقَ، وَإِنْ مَاتَ الْمُكَاتَبُ وَعَلَيْهِ دَيْنٌ لَمْ يُحَاصَّ الْغُرَمَاءَ سَيِّدُهُ بِكِتَابَتِهِ، وَكَانَ الْغُرَمَاءُ أَوْلَى بِذَلِكَ مِنْ سَيِّدِهِ، وَإِنْ عَجَزَ الْمُكَاتَبُ وَعَلَيْهِ دَيْنٌ لِلنَّاسِ، رُدَّ عَبْداً مَمْلُوكاً لِسَيِّدِهِ، وَكَانَتْ دُيُونُ النَّاسِ فِي ذِمَّةِ الْمُكَاتَبِ، وَلَا يَدْخُلُونَ مَعَ سَيِّدِهِ فِي شَيْءٍ مِنْ ثَمَنِ رَقَبَتِهِ.","امام مالک رحمہ اللہ نے فرمایا: ہمارے ہاں اس حکم پر اتفاق ہے کہ بے شک کسی غلام سے جب اس کا آقا مکاتبت کر لے تو آقا کے حق میں یہ جائز نہیں کہ اس کے لیے کوئی شخص غلام کے بدل کتابت کی ضمانت اٹھائے (اس صورت میں کہ) اگر غلام مر جائے یا عاجز آئے اور یہ عمل مسلمانوں کی سنت نہیں ہے اور یہ (ضمانت کا درست نہ ہونا) اس وجہ سے ہے کہ اگر کوئی شخص مکاتب کے آقا کے لیے اس کے ذمے عائد ہونے والے بدل کتابت کی ضمانت لے لے، پھر وہ آقا اس ضمانت اٹھانے والے کی طرف رجوع کرے (اور اس سے بدل کتابت لے لے) تو وہ اس کا مال باطل (اور ناجائز ہی) وصول کرے گا (کیونکہ مکاتب غلام کو یا تو خرید کر اپنا غلام بنا کر اپنی ملکیت میں رکھنا جائز ہے، یا اسے خرید کر آزاد کرنا جائز ہے لیکن) نہ تو اس ضامن نے مکاتب کو خریدا ہے کہ اس سے وصول کیا جانے والا مال کسی ایسی چیز کی قیمت شمار ہو سکے جو اس کی ملکیت بنتی اور نہ مکاتب غلام آزاد ہوا ہے کہ وہ (ضامن سے حاصل شدہ مال) غلام کے لیے ثابت ہونے والی (آزادی کی) حرمت کی قیمت (شمار) ہو سکے، (الغرض ضامن سے لیا ہوا مال نہ تو ثمن (قیمت) ہے اور نہ ہی بدل کتابت ہے بلکہ ناجائز اور باطل ہے، چنانچہ اگر وہ مکاتب غلام عاجز آ جائے گا تو اپنے آقا کی طرف لوٹ آئے گا اور وہ غلام ہی رہے گا اور اس کی ملکیت میں رہے گا اور یہ (ضمانت کا ناجائز ہونا) اس وجہ سے (بھی) ہے کہ بدل کتابت کوئی ایسا قرض نہیں ہے جو (مکاتب کی گردن پر لازم اور) ثابت ہو کہ مکاتب کے آقا کے لیے جس کی چٹی (ضمانت) اٹھائی جائے (بلکہ) بلاشبہ وہ تو صرف اور صرف ایک ایسی چیز ہے کہ اگر مکاتب اسے ادا کر دے گا تو آزاد ہو جائے گا (اور ادا نہ کرے گا تو آزاد نہ ہو پائے گا) اور اگر مکاتب اس حال میں مر جائے کہ اس پر (لوگوں کا) قرضہ ہو تو بدل کتابت میں اس کا آقا قرض خواہوں کے ساتھ حصے دار نہ ہوگا اور آقا کی بجائے قرض خواہ ہی اس (کتابت والی رقم) کے زیادہ حق دار ہوں گے (اور یہ بھی اس بات کی دلیل ہے کہ بدل کتابت کی حیثیت قرض جیسی نہیں ہے، یہ آقا کا غلام پر قرض نہیں ہوتا، ورنہ تو وہ بھی دوسرے قرض خواہوں کی طرح برابر کا حصے دار اور حقدار ہوتا) ..... اور اگر مکاتب اس حال میں عاجز آ جائے کہ اس پر لوگوں کا قرضہ ہو تو وہ خود غلامی میں لوٹ آئے گا اور اپنے آقا کی ملکیت میں چلا جائے گا اور لوگوں کے قرضے ایک مکاتب کے ذمے رہیں گے (لیکن) اس غلام کی گردن کی قیمت میں وہ قرض خواہ اس کے آقا کے ساتھ (شریک ہو کر) داخل نہیں ہو سکیں گے۔","..... اور یہ بھی اس بات کی دلیل ہے کہ بدل کتابت کی حیثیت قرض کی طرح نہیں کیونکہ غلام کے عاجز آنے کی صورت میں کتابت ختم ہو جاتی ہے اور قرضے ختم نہیں ہوتے، نیز اس کی حیثیت لوگوں کے قرض جیسی ہوتی تو لوگ بھی مذکورہ صورت حال میں اس کی گردن کی قیمت میں برابر کے شریک ہوتے۔","قَالَ مَالِكٌ: إِذَا كَاتَبَ الْقَوْمُ جَمِيعاً كِتَابَةً وَاحِدَةً، وَلَا رَحِمَ بَيْنَهُمْ يَتَوَارَثُونَ بِهَا، فَإِنَّ بَعْضَهُمْ حُمَلَاءُ عَنْ بَعْضٍ وَلَا يَعْتِقُ بَعْضُهُمْ دُونَ بَعْضٍ، حَتَّى يُؤَدُّوا الْكِتَابَةَ كُلَّهَا، فَإِنْ مَاتَ أَحَدٌ مِنْهُمْ وَتَرَكَ مَالاً هُوَ أَكْثَرُ مِنْ جَمِيعِ مَا عَلَيْهِمْ أُدِّيَ عَنْهُمْ جَمِيعُ مَا عَلَيْهِمْ، وَكَانَ فَضْلُ الْمَالِ لِسَيِّدِهِ، وَلَمْ يَكُنْ لِمَنْ كَاتَبَ مَعَهُ مِنْ فَضْلِ الْمَالِ شَيْءٌ، وَيَتْبَعُهُمُ السَّيِّدُ بِحِصَصِهِمُ الَّتِي بَقِيَتْ عَلَيْهِمْ مِنَ الْكِتَابَةِ الَّتِي قُضِيَتْ مِنْ مَالِ الْهَالِكِ، لِأَنَّ الْهَالِكَ إِنَّمَا كَانَ تَحَمَّلَ عَنْهُمْ، فَعَلَيْهِمْ أَنْ يُؤَدُّوا مَا عَتَقُوا بِهِ مِنْ مَالِهِ، وَإِنْ كَانَ لِلْمُكَاتَبِ الْهَالِكِ وَلَدٌ حُرٌّ لَمْ يُولَدْ فِي الْكِتَابَةِ، وَلَمْ يُكَاتَبْ عَلَيْهِ، لَمْ يَرِثْهُ لِأَنَّ الْمُكَاتَبَ لَمْ يُعْتَقْ حَتَّى مَاتَ.","امام مالک رحمہ اللہ نے فرمایا: جب کچھ (غلام) لوگوں نے ایک ہی عقد کتابت میں مکاتبت کی اور ان کی آپس میں کوئی ایسی رشتہ داری بھی نہ ہو جس کے ساتھ وہ ایک دوسرے کے وارث بن سکتے ہوں تو یقیناً (رشتہ داری نہ ہونے کے باوجود) ان میں سے بعض، بعض کی طرف سے ضامن ہوں گے (سب ایک دوسرے کا بوجھ اٹھائیں گے) ان میں سے کوئی بھی کسی دوسرے کے بغیر آزاد نہ ہو سکے گا (خواہ کسی نے اپنی قیمت سے زیادہ رقم ادا کی ہو اور کسی نے کچھ بھی ادا نہ کیا ہو) یہاں تک کہ وہ مکمل بدل کتابت ادا کر دیں (تو تبھی اکٹھے آزاد ہو پائیں گے) چنانچہ اگر ان مکاتب غلاموں میں سے کوئی مر جائے اور اتنا مال چھوڑ جائے جو ان پر لازم مکمل بدل کتابت سے بھی زیادہ ہو تو اس تر کے میں سے ان سب کی طرف سے وہ سب کچھ ادا کر دیا جائے گا جو ان پر (کتابت کی رقم کے طور پر) لازم تھا اور (میت کا) زائد مال (ترکہ) آقا کا ہوگا اور اس (فوت شدہ مکاتب غلام) کے ساتھ جس (جس دوسرے غلام) نے مکاتبت کی تھی اس کے لیے زائد تر کے میں سے کچھ نہ ہوگا (کیونکہ وہ آپس میں رشتہ دار تو ہیں نہیں اس لیے انھیں وراثت نہیں ملے گی، البتہ غلامی کے تعلق کی وجہ سے آقا وارث بن جائے گا، بہر حال وہ بوجھ میں بھی اکٹھے تھے اور آزاد بھی اکٹھے ہوئے ہیں) اور اب آقا ان سب (آزاد ہونے والوں) سے ان کے ان حصوں کا مطالبہ کرے گا جو ان پر بدل کتابت سے باقی رہ گئے تھے اور فوت شدہ مکاتب غلام کے تر کے سے ادا کیے گئے تھے (دراصل اس مکاتب کے سارے مال کا وارث اس کا آقا ہی تھا، لیکن اکٹھے عقد کتابت کی وجہ سے اس کے مال کو بدل کتابت میں صرف کر دیا گیا تو اب باقی آزاد ہونے والے غلام اپنے آقا کو وہ رقم ادا کریں گے جو ان کے ذمے بدل کتابت میں سے واجب تھی) کیونکہ بلاشبہ فوت شدہ (غلام) نے ان کی طرف سے صرف ضمانت اٹھائی تھی تو اب ان پر چونکہ آزادی کی نعمت اور وسعت آ چکی ہے لہذا ان پر لازم ہے کہ وہ اس کا وہ مال ادا کر دیں جس کے ذریعے وہ آزاد ہوئے ہیں، (اور یہ سودا مہنگا نہیں ہے، ان کو آزادی کی نعمت مل چکی ہے بلکہ اس کے مرنے کی وجہ سے جلدی آزاد ہو گئے ہیں لہذا جو تھوڑا تھوڑا حصہ آتا ہے انھیں چاہیے کہ اس فوت شدہ کے وارث یعنی آقا کو ادا کر دیں) اور اگر فوت ہونے والے مکاتب کا کوئی آزاد لڑکا ہو جو (عقد کتابت کے بعد) زمانہ کتابت میں پیدا نہ ہوا ہو اور نہ اس پر مکاتبت واقع ہوئی ہو تو وہ (آزاد بیٹا) اس مکاتب (باپ) کا وارث نہیں بنے گا کیونکہ مکاتب جب فوت ہوا تھا تو آزاد نہ تھا۔","..... اور یہ اصول ہے کہ آزاد اور غلام رشتہ دار آپس میں وارث نہیں بن سکتے کیونکہ غلامی ’’موانع الارث‘‘ (وراثت سے مانع چیزوں) میں سے ہے جو کہ تین ہیں قتل، رق (غلامی) اور اختلاف دین (کفر و اسلام)...... اگر مکاتبت کے دوران میں کوئی بچہ پیدا ہوا ہو یا اس کی پیدائش تو دور غلامی کی ہو لیکن عقد کتابت میں وہ باپ کے ساتھ شامل ہو تو پھر بھی ان کی باہمی وراثت نہ چلے گی کیونکہ اس وقت بھی باپ کی حالت غلامی میں موت وارث نہیں بننے دیتی ..... ہمارے خیال میں مکاتب کا جس قدر حصہ آزاد ہو چکا ہوتا ہے اتنے حصے میں اس پر آزادی کے بعض احکامات صادر ہوتے ہیں جن میں سے ایک وراثت ہے، چنانچہ یہ بات تو حدیث سے ثابت ہے کہ مکاتب غلام اپنے آزاد حصے کے لحاظ سے خود وارث بنتا ہے۔ (ابوداود: ۴۵۸۲، ترمذی: ۱۲۵۹، اس کی سند حسن ہے) لہذا اسی آزاد حصے میں اس کا وارث بھی بنا جائے گا۔ واللہ اعلم"],"422":["§خلاصۃ الباب","اس باب میں ایک موقوف روایت یعنی اثر صحابی ہے جو سنداً ضعیف ہے، نیز امام مالک رحمہ اللہ کے سات فتاویٰ مذکور ہیں۔","..... قطاعت میں قاف پر زبر اور زیر دونوں جائز ہیں، یہ لفظ باب مفاعلہ کے مصدر مقاطعہ سے ماخوذ ہے اور اسم مصدر ہے، مقاطعہ کے لغوی معنی تو کسی متعین اجرت پر کام کا معاہدہ کرنے کے ہیں اور اصطلاحاً اس کا ..... مطلب یہ ہے کہ آقا بدل کتابت چھوڑ کر اس کی جگہ کچھ نقد مال لینے پر راضی ہو جائے اور اس طرح مکاتب کو جلد آزادی مل جاتی ہے، یوں غلام اپنے آقا کی طرف سے بدل کتابت کے مطالبے کو منقطع کر دیتا ہے اور اس کی آزادی کی حرمت قطعی طور پر ثابت ہو جاتی ہے ... یاد رہے قطاعت کا عمل دو اعتبار سے احسان ہوتا ہے، ایک یہ کہ غلام کو جلدی آزادی مل جاتی ہے اور دوسرا یہ کہ نقد قیمت میں کمی کر دی جاتی ہے۔ اور قطاعت دراصل مکاتبت کی فرع ہے۔ اگر عقد کتابت نہ ہو تو قطاعت بھی نہیں ہو سکتی۔"],"423":["§خلاصۃ الباب","اس باب میں کوئی روایت نہیں ہے، البتہ امام مالک رحمہ اللہ کے چار فتاوی جات مذکور ہیں۔","..... غلاموں کے ذمے پڑنے والی دیت میں دو صورتیں ہوتی ہیں: ایک یہ کہ آقا اسے ادا کر دے اور دوسری یہ کہ اس (مجرم) غلام ہی کو دیت کے طور پر مظلوموں کے حوالے کر دیا جاتا ہے، تو کیا مکاتب پر بھی یہی صورت لاگو ہوگی یا نہیں، اسی کی تفصیل مذکورہ باب میں بیان کی جارہی ہے۔ نیز اگر غلاموں کو زخمی کر دیا جائے اور ان زخموں میں دیت پڑتی ہو تو ان کی قیمت کا حساب لگایا جاتا ہے، چنانچہ اس زخم کی بنا پر غلام کی قیمت میں جس قدر کمی واقع ہوئی ہوا سے بطور دیت وصول کیا جاتا ہے اور اگر انھیں قتل کر دیا جائے تو ان کی مکمل قیمت بطور دیت لی جاتی ہے..... رہا مکاتب غلام کا معاملہ تو امام مالک رحمہ اللہ اسے عام غلاموں کی سی حیثیت دیتے ہیں، حالانکہ رسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے: «يُوْدَى مَا اَدُّى مِنْ مُكَاتَبَتِهِ دِيَةَ الْحُرِّ وَمَا بَقِيَ دِيَةَ الْمَمْلُوكِ» وہ جتنا بدل کتابت ادا کر چکا ہو اس کے مطابق اسے آزاد آدمی کی دیت ملے گی اور باقی ماندہ میں غلام کی دیت ملے گی۔ (ابوداود: ۴۵۸۱، ترمذی: ۱۲۵۹، نسائی: ۴۸۱۲، اس کی سند صحیح ہے) قَالَ مَالِكٌ : أَحْسَنُ مَا سَمِعْتُ فِي الْمُكَاتَبِ يَجْرَحُ الرَّجُلَ جَرْحاً يَقَعُ فِيهِ الْعَقْلُ عَلَيْهِ : أَنَّ الْمُكَاتَبَ إِنْ قَوِىَ عَلَى أَنْ يُؤَدِّيَ عَقْلَ ذَلِكَ الْجَرْحِ مَعَ كِتَابَتِهِ أَدَاهُ، وَكَانَ عَلَى كِتَابَتِهِ، فَإِنْ لَمْ يَقْوَ عَلَى ذَلِكَ فَقَدْ عَجَزَ عَنْ كِتَابَتِهِ، وَذَلِكَ أَنَّهُ يَنْبَغِي أَنْ يُؤَدِّيَ عَقْلَ ذَلِكَ الْجَرْحِ قَبْلَ الْكِتَابَةِ، فَإِنْ هُوَ عَجَزَ عَنْ أَدَاءِ عَقْلِ ذَلِكَ الْجَرْحِ خُيِّرَ سَيِّدُهُ، فَإِنْ أَحَبَّ أَنْ يُؤَدِّيَ عَقْلَ ذَلِكَ الْجَرْحِ فَعَلَ، وَأَمْسَكَ غُلامَهُ، وَصَارَ عَبْداً مَمْلُوكاً، وَإِنْ شَاءَ أَنْ يُسَلِّمَ الْعَبْدَ إِلَى الْمَجْرُوحِ أَسْلَمَهُ، وَلَيْسَ عَلَى السَّيِّدِ أَكْثَرُ مِنْ أَنْ يُسَلِّمَ عَبْدَهُ .","امام مالک رحمہ اللہ نے فرمایا: میں نے مکاتب کے متعلق سب سے بہترین بات یہ سنی ہے کہ جو مکاتب غلام کسی شخص کو ایسا زخم لگا دیتا ہے جس میں اس پر دیت واجب ہوتی ہے تو بلاشبہ اگر وہ مکاتب اپنے بدل کتابت کے ساتھ ساتھ اس زخم کی دیت ادا کرنے پر قدرت رکھتا ہو تو وہ اسے ادا کرے گا اور اپنی مکاتبت پر بھی قائم رہے گا اور اگر وہ اس پر قدرت نہ رکھتا ہو تو وہ اپنی کتابت سے عاجز (شمار) ہوگا اور (فیصلہ) اس وجہ سے ہے کہ اس کے لیے درست یہی ہے کہ وہ بدل کتابت سے پہلے اس زخم کی دیت ادا کرے، چنانچہ اگر وہ اس زخم کی دیت سے عاجز آ گیا تو اس کے مالک کو اختیار ہے، اگر وہ پسند کرے تو اس زخم کی دیت ادا کر دے تو وہ ایسا کر لے اور اپنے غلام کو (اپنے پاس) روکے رکھے اور (اس صورت میں) وہ (مکاتب غلام) اس کا مملوک غلام بن جائے گا اور (مکاتبت سے واپس مکمل غلامی میں لوٹ آئے گا، آقا کو دوسرا اختیار یہ ہے کہ) اگر وہ چاہے تو اس (مکاتب) غلام کو زخمی شخص (کی دیت کے عوض اسی) کے سپرد کر دے تو وہ اسے سپرد کر سکتا ہے اور اس آقا پر اس سے زیادہ کچھ (لازم) نہیں ہے کہ وہ اپنے غلام کو اس (مظلوم) کے سپرد کر دے۔","..... یہ درست نہیں کہ زخمی ہونے والا شخص یہ دعویٰ کر دے کہ یہ غلام تھوڑی قیمت والا ہے اور میرے زخم کی دیت زیادہ ہے لہذا کچھ اور بھی ادا کرو۔ آقا پر زیادہ سے زیادہ وہی غلام بدلے میں دینا لازم ہے، غلام سے زیادہ کچھ اور بھی دینا ضروری نہیں، ہاں اگر وہ دینا چاہے تو اس کی مرضی ہے۔","قَالَ مَالِكٌ فِي الْقَوْمِ يُكَاتَبُونَ جَمِيعاً، فَيَجْرَحُ أَحَدُهُمْ جَرْحاً فِيهِ عَقْلٌ . قَالَ مَالِكٌ : مَنْ جَرَحَ مِنْهُمْ جَرْحاً فِيهِ عَقْلٌ قِيلَ لَهُ وَلِلَّذِينَ مَعَهُ فِي الْكِتَابَةِ : أَدُّوا جَمِيعاً عَقْلَ ذَلِكَ الْجَرْحِ . فَإِنْ أَدَّوْا ثَبَتُوا عَلَى كِتَابَتِهِمْ، وَإِنْ لَمْ يُؤَدُّوا فَقَدْ عَجَزُوا ، وَيُخَيَّرُ سَيِّدُهُمْ،","امام مالک رحمہ اللہ نے ان چند غلاموں کے بارے میں فرمایا جو اکٹھے مکاتب بنائے جاتے ہیں (مثلاً غلام اور اس کے بیوی بچے وغیرہ) پھر ان میں سے کوئی (غلام کسی شخص کو) ایسا زخم لگا دیتا ہے جس میں دیت واجب ہو، تو امام مالک رحمہ اللہ نے فرمایا: ان میں سے جس کسی نے دیت والا زخم لگایا تو اس سے، اور اس کے ساتھ جو جو لوگ کتابت فَإِنْ شَاءَ أَدَّى عَقْلَ ذَلِكَ الْجَرْحِ وَرَجَعُوا عَبِيداً لَهُ جَمِيعاً، وَإِنْ شَاءَ أَسْلَمَ الْجَارِحَ وَحْدَهُ، وَرَجَعَ الآخَرُونَ عَبِيداً لَهُ جَمِيعاً بِعَجْزِهِمْ عَنْ أَدَاءِ عَقْلِ ذَلِكَ الْجَرْحِ الَّذِي جَرَحَ صَاحِبُهُمْ .","میں شامل تھے، ان سب سے کہا جائے گا کہ سب مل کر اس زخم کی دیت ادا کرو، چنانچہ اگر تو وہ اسے ادا کر دیں تو اپنی مکاتبت پر قائم رہیں گے اور اگر وہ دیت ادا نہ کر سکیں تو یقیناً وہ (سب کے سب) عاجز شمار ہوں گے، ان کے آقا کو یہ اختیار دے دیا جائے گا کہ اگر چاہے تو اس زخم کی دیت ادا کر دے اور یہ سب (مکاتب غلام) اس کی طرف غلام بن کر لوٹ آئیں گے (مکاتبت ختم اور پہلے کی طرح کی غلامی بحال ہو جائے گی) اور اگر وہ آقا چاہے تو اکیلے زخمی کرنے والے غلام کو (زخمی شخص کے) سپرد کر دے اور باقی سب (اس مکاتب غلام کے ساتھی) اس کی (کامل) غلامی میں لوٹ آئیں، اس وجہ سے کہ وہ اس زخم کی دیت ادا کرنے سے عاجز آ چکے ہیں جو ان کے ساتھی نے لگایا تھا۔","قَالَ مَالِكٌ : الأَمْرُ الَّذِي لاَ اخْتِلاَفَ فِيهِ عِنْدَنَا أَنَّ الْمُكَاتَبَ إِذَا أُصِيبَ بِجَرْحٍ يَكُونُ لَهُ فِيهِ عَقْلٌ، أَوْ أُصِيبَ أَحَدٌ مِنْ وَلَدِ الْمُكَاتَبِ الَّذِينَ مَعَهُ فِي كِتَابَتِهِ ، فَإِنَّ عَقْلَهُمْ عَقْلُ الْعَبِيدِ فِي قِيمَتِهِمْ ، وَأَنَّ مَا أُخِذَ لَهُمْ مِنْ عَقْلِهِمْ يُدْفَعُ إِلَى سَيِّدِهِمُ الَّذِي لَهُ الْكِتَابَةُ، وَيُحْسَبُ ذَلِكَ لِلْمُكَاتَبِ فِي آخِرِ كِتَابَتِهِ ، فَيُوضَعُ عَنْهُ مَا أَخَذَ سَيِّدُهُ مِنْ دِيَةِ جَرْحِهِ.","امام مالک رحمہ اللہ نے فرمایا: وہ معاملہ جس میں ہمارے ہاں کوئی اختلاف نہیں، یہ ہے کہ بے شک جب کسی مکاتب غلام کو ایسا زخم پہنچا دیا جائے جس میں اس کے لیے دیت لازم ہوتی ہو، یا مکاتب کے ساتھ اس کی وہ اولاد جو عقد کتابت میں اس کے ساتھ شامل تھی ان میں سے کسی کو زخمی کر دیا جائے تو (امام مالک رحمہ اللہ نے فرمایا:) بلاشبہ ان کی دیت عام غلاموں جیسی ہوگی جو ان کی قیمتوں کے حساب سے لازم ہوتی ہے اور یقیناً ان کی دیت میں سے جو کچھ بھی وصول کیا جائے گا وہ اس آقا کو دے دیا جائے گا جس نے انھیں مکاتب بنایا تھا اور اس (دیت) کا بدل کتابت (کی ادائیگی) کے اخیر میں حساب لگایا جائے گا، چنانچہ اس کا آقا اس کے زخم کی جس قدر دیت (کی رقم) لے چکا ہو وہ اس (کے بدل کتابت) سے ختم کر دی جائے گی۔","قَالَ مَالِكٌ : وَتَفْسِيرُ ذَلِكَ أَنَّهُ كَأَنَّهُ كَاتَبَهُ عَلَى ثَلَاثَةِ آلَافِ دِرْهَمٍ ، وَكَانَ دِيَةُ جَرْحِهِ الَّذِي أَخَذَهَا سَيِّدُهُ أَلْفَ دِرْهَمٍ ، فَإِذَا أَدَّى الْمُكَاتَبُ إِلَى سَيِّدِهِ أَلْفَيْ دِرْهَمٍ، فَهُوَ حُرٌّ ، وَإِنْ كَانَ الَّذِي بَقِيَ عَلَيْهِ مِنْ كِتَابَتِهِ أَلْفَ","امام مالک رحمہ اللہ نے فرمایا: اس کی تفسیر یہ ہے کہ (مثلاً) اس نے اس سے تین ہزار درہم پر کتابت کر رکھی تھی اور اس کے زخم کی جو دیت اس کے آقا نے وصول کی تھی وہ ایک ہزار درہم ہو تو جب مکاتب غلام اپنے آقا کو دو ہزار درہم ادا کر دے گا تو وہ آزاد ہو جائے گا، اور اگر اس کے بدل کتابت دِرْهَمٍ، وَكَانَ الَّذِي أَخَذَ مِنْ دِيَةِ جَرْحِهِ أَلْفَ دِرْهَمٍ، فَقَدْ عَتَقَ، وَإِنْ كَانَ عَقْلُ جَرْحِهِ أَكْثَرَ مِمَّا بَقِيَ عَلَى الْمُكَاتَبِ، أَخَذَ سَيِّدُ الْمُكَاتَبِ مَا بَقِيَ مِنْ كِتَابَتِهِ وَعَتَقَ، وَكَانَ مَا فَضَلَ بَعْدَ أَدَاءِ كِتَابَتِهِ لِلْمُكَاتَبِ, وَلاَ يَنْبَغِي أَنْ يُدْفَعَ إِلَى الْمُكَاتَبِ شَيْءٌ مِنْ دِيَةِ جَرْحِهِ فَيَأْكُلَهُ وَيَسْتَهْلِكَهُ، فَإِنْ عَجَزَ رَجَعَ إِلَى سَيْدِهِ أَعْوَرَ أَوْ مَقْطُوعَ اليَدِ أَوْ مَعْضُوبَ الْجَسَدِ، وَإِنَّمَا كَاتَبَهُ سَيِّدُهُ عَلَى مَالِهِ وَكَسْبِهِ، وَلَمْ يُكَاتِبُهُ عَلَى أَنْ يَأْخُذَ ثَمَنَ وَلَدِهِ، وَلاَ مَا أُصِيبَ مِنْ عَقْلِ جَسَدِهِ، فَيَأْكُلَهُ وَيَسْتَهْلِكَهُ، وَلَكِنْ عَقْلُ جِرَاحَاتِ الْمُكَاتَبِ، وَوَلَدِهِ الَّذِينَ وُلِدُوا فِي كِتَابَتِهِ، أَوْ كَاتَبَ عَلَيْهِمْ، يُدْفَعُ إِلَى سَيِّدِهِ، وَيُحْسَبُ ذَلِكَ لَهُ فِي آخِرِ كِتَابَتِهِ .","میں سے جو رقم باقی رہ گئی تھی وہ ایک ہزار درہم تھی اور آقا نے اس کے زخم کی جو دیت وصول کی وہ بھی ایک ہزار تھی تو وہ (فوراً دیت ملتے ہی) آزاد ہو جائے گا، اور اگر اس کے زخم کی دیت اس (رقم) سے زیادہ ہو جو مکاتب کے ذمے باقی تھی تو اس کا آقا اس کے بدل کتابت میں سے باقی ماندہ (کے برابر رقم دیت میں سے) وصول کر لے گا اور غلام آزاد ہو جائے گا اور زر کتابت کی ادائیگی کے بعد جو کچھ بھی (دیت میں سے) زائد بچے گا وہ مکاتب غلام کا (مال) ہوگا اور یہ درست نہیں کہ اس کے زخم کی دیت میں سے کوئی چیز مکاتب غلام کے حوالے کی جائے کہ جسے وہ کھا پی لے اور ضائع کر بیٹھے، پھر اگر وہ (بدل کتابت کی ادائیگی سے) عاجز آ جائے تو اپنے آقا کی طرف (مکمل غلامی کے ساتھ) اس حال میں لوٹے گا کہ کانا ہو چکا ہو یا اس کا ہاتھ کٹا ہوا ہو یا جسم پر داغ لگا ہوا ہو (لہذا دیت آقا کے قبضے میں جائے گی تاکہ وہ اسے بدل کتابت میں سے کاٹ لے اور غلام کو آزاد کر دے ورنہ تو دیت کا مال بھی غلام کے ہاتھوں ضائع ہو جائے گا اور بعد میں معذور ہونے کی وجہ سے قوی اندیشہ یہی ہے کہ وہ عاجز آ کر آقا کو فائدہ پہنچانے کی بجائے الٹا نقصان میں رکھے گا اور اس پر بوجھ بنا رہے گا۔) اور بلاشبہ اس کے آقا نے اس سے اس کے مال اور اس کی کمائی میں مکاتبت کی تھی، اس بات پر مکاتب نہیں بنایا تھا کہ (مذکورہ دیت والی صورت میں) وہ اپنے بچوں کی قیمت حاصل کر سکے اور نہ وہ قیمت جو اس کے اپنے جسم (میں پہنچنے والے زخم) کی دیت میں سے حاصل ہوئی کہ اسے وصول کرے، پھر اسے کھا پی کر تباہ کر بیٹھے (لہذا مکاتب غلام کے حوالے کچھ نہ کیا جائے گا) بلکہ مکاتب کے (اپنے زخموں کی دیت اور اس کے زمانہ مکاتبت میں پیدا ہونے والے بچوں (کے زخموں) کی دیت یا (ان بچوں کی دیت جو پیدا تو مکاتبت سے پہلے ہی ہو گئے تھے لیکن) اس نے (ان میں سے) جن پر مکاتبت کی ہوئی تھی (ان سب کی دیت) اس کے آقا ہی کے حوالے کی جائے گی اور اس کے بدل کتابت کے اخیر میں اس کا حساب لگایا جائے گا (اور اسے بدل کتابت میں شامل کر کے مکاتب کو جلد آزاد کر دیا جائے گا)۔"],"424":["§خلاصۃ الباب","اس باب میں کوئی روایت نہیں ہے، صرف امام مالک رحمہ اللہ کے چھ فتاوی جات مذکور ہیں۔","..... جمہور کے نزدیک مکاتب غلام کی خرید و فروخت درست ہے جیسا کہ سیدہ عائشہ رضی اللہ عنہا نے سیدہ بریرہ رضی اللہ عنہا کو خریدا تھا۔ امام ابو حنیفہ اور امام شافعی رحمہما اللہ کے نزدیک اسے بیچا نہیں جا سکتا۔ امام مالک رحمہ اللہ کے اس بارے میں دو اقوال ہیں، جواز کا بھی اور عدم جواز کا بھی اور ان کا یہ دوسرا قول ہی ان کے متعلق زیادہ مشہور ہے..... تو اس باب میں دراصل وہ مکاتب غلام کی کتابت والی رقم کی خرید و فروخت کے مسائل بیان کر رہے ہیں، چنانچہ وہ اس میں بعض احتیاطی تدابیر بیان کر رہے ہیں، دراصل مکاتب غلام سے بدل کتابت کی صورت میں کسی چیز، مال یا رقم کے عوض مکاتبت کی جاتی ہے، پھر اس کو بیچ کر اس کی قیمت لینا مقصود ہو تو گویا بدل کتابت کو بیچتے وقت اس کا وصول کی جانے والی چیز یا رقم سے تبادلہ ہو رہا ہوتا ہے اور نبی کریم صلی اللہ علیہ وسلم نے کچھ چیزوں یعنی سونا چاندی، گندم، جو، نمک اور کھجور کے باہمی تبادلے میں یہ حکم فرمایا ہے کہ اگر ان کا ہم جنس چیز سے تبادلہ ہو مثلاً سونے کا سونے سے یا گندم کے بدلے گندم ہو تو دو شرطیں لازم ہیں: (۱) دونوں جانب وزن برابر ہو اور (۲) سودا نقد و نقد ہو..... اور اگر ایک جنس کا تبادلہ دوسری جنس سے ہو، مثلاً سونے کا چاندی سے یا گندم کا جو سے تو پھر ایک شرط ہے کہ سودا دونوں طرف سے نقد ہو البتہ وزن میں کمی بیشی جائز ہے، تو اگر مذکورہ شرطوں میں سے کوئی مفقود ہو تو یہ سودا سود شمار ہوگا۔ (مسلم: ۱۵۸۴، ۱۵۹۶) یاد رہے کہ سونا چاندی یا ان کی جگہ پر چلنے والی رسید یعنی کاغذی نوٹ خواہ روپیہ ہو یا ڈالر، یا ریال یا یورو وغیرہ تو انھیں نقدی کہا جاتا ہے اور گندم، جو، نمک وغیرہ کو اجناس کہتے ہیں، چنانچہ نقدی ہو یا اجناس میں سے کچھ اور اس کا ہم جنس چیز سے تبادلہ ہو تو اس میں وزن کے برابر اور نقد و نقد ہونے کی شرط ہے، اگر وزن برابر نہ ہو تو اس کا نام ’’رِبَا الْفَضْلِ‘‘ (کسی زیادتی والا سود) ہے اور نقد و نقد تبادلہ نہ ہو تو اسے ’’ربا النسيئة‘‘ (ادھار والا سود) کہتے ہیں، اگر صرف نقدیوں یعنی سونے یا چاندی یا نوٹ کا آپس میں الگ جنس کے ساتھ تبادلہ ہو یا صرف اجناس کا آپس میں ایک دوسری سے تبادلہ ہو تو پھر صرف ایک پابندی ہے کہ سودا نقد و نقد ہو ورنہ یہ ’’رِبَا النَّسِيئَةِ‘‘ بن جائے گا..... ہاں اگر ایک طرف کوئی نقدی ہو اور دوسری طرف اجناس میں سے کوئی چیز ہو مثلاً سونے کے بدلے گندم یا روپے کے بدلے کھجور وغیرہ تو پھر نقد و نقد کی پابندی بھی نہیں رہتی اور نہ تو دنیا میں ادھار کا سلسلہ ہی حرام ہو جاتا اور انسانیت مشقت میں پڑ جاتی۔","قَالَ مَالِكٌ : إِنَّ أَحْسَنَ مَا سُمِعَ فِي الرَّجُلِ يَشْتَرِى مُكَاتَبَ الرَّجُلِ : أَنَّهُ لاَ يَبِيعُهُ إِذَا كَانَ كَاتَبَهُ بِدَنَانِيرَ أَوْ دَرَاهِمَ ، إِلَّا بِعَرْضٍ مِنَ","امام مالک رحمہ اللہ نے فرمایا: میں نے سب سے اچھی بات یہ سنی ہے اس آدمی کے متعلق جو کسی دوسرے آدمی کا مکاتب غلام خریدنا چاہتا ہے کہ بلاشبہ اس کے آقا نے جب اس الْعُرُوضِ يُعَجِّلُهُ وَلَا يُؤَخِّرُهُ، لِأَنَّهُ إِذَا أَخَّرَهُ كَانَ دَيْناً بِدَيْنٍ، وَقَدْ نُهِيَ عَنِ الْكَالِءِ بِالْكَالِءِ. قَالَ: وَإِنْ كَاتَبَ الْمُكَاتَبَ سَيِّدُهُ بِعَرْضِ مِنَ الْعُرُوضِ مِنَ الْإِبِلِ أَوِ الْبَقَرِ أَوِ الْغَنَمِ أَوِ الرَّقِيقِ، فَإِنَّهُ يَصْلُحُ لِلْمُشْتَرِي أَنْ يَشْتَرِيَهُ بِذَهَبٍ أَوْ فِضَّةٍ أَوْ عَرْضِ مُخَالِفِ لِلْعُرُوضِ الَّتِي كَاتَبَهُ سَيِّدُهُ عَلَيْهَا، يُعَجِّلُ ذَلِكَ وَلَا يُؤَخِّرُهُ.","سے دیناروں یا درہموں کے عوض مکاتبت کی ہو تو وہ اسے صرف اور صرف سامانوں میں سے کسی سامان کے بدلے ہی خرید سکتا ہے کسی نقدی کے عوض نہیں خرید سکتا کیونکہ یہ نقدی کا نقدی کے ساتھ تبادلہ بنے گا جس میں نقد ونقد کی لازمی شرط ہے اور ہم جنس نقدی کا تبادلہ ہو تو وزن برابر ہونا بھی شرط ہے، بہر حال مکاتب کی بیچ میں ایک جانب بدل کتابت ہوتا ہے اور وہ ادھار اور قرض کی سی حیثیت رکھتا ہے، اور اس کے بدلے صرف کوئی سامان ہی ہو سکتا ہے) جسے وہ فی الفور نقد ادا کرے گا اور وہ اسے موخر نہ کرے کیونکہ اگر وہ اسے موخر کرے گا تو یہ قرض کے بدلے قرض ہو جائے گا اور ادھار کے بدلے خرید وفروخت سے منع کر دیا گیا ہے۔ امام مالک رحمہ اللہ نے فرمایا: اور اگر مکاتب کے آقا نے اس (مکاتب) سے سامانوں میں سے کسی سامان مثلاً اونٹ یا گائے یا بکری یا غلام کے بدلے مکاتبت کی ہو تو پھر بلاشبہ خریدار کے لیے درست ہے کہ وہ مکاتب غلام کو سونے یا چاندی کے بدلے میں خرید لے یا جن سامانوں کے عوض آقا نے اس سے مکاتبت کی ہو ان کے علاوہ کسی اور سامان کے عوض، (اسے خرید لے اور) اسے بھی وہ نقد ہی ادا کرے گا اور اس میں تاخیر یعنی ادھار نہ کرے گا۔","...... امام احمد رحمہ اللہ فرماتے ہیں کہ اگرچہ اس موضوع پر کوئی مرفوع روایت یعنی حدیث نبوی تو صحیح ثابت نہیں ہے لیکن قرض کی قرض کے بدلے (یا ادھار کی ادھار کے بدلے) بیع حرام ہونے پر امت کا اجماع ہے۔ (نیل الاوطار: ۵۲۷/۳، الروضة الندیة: ۲۰۸/۲) رہیں وہ احادیث نبویہ جن میں صراحتاً اس سے ممانعت ہے۔ (حاکم: ۵۷/۲، بیہقی: ۲۹۰/۵، دار قطنی: ۷۱/۳، التلخیص الحبیر: ۲۶/۳) تو یہ ضعیف ہیں کیونکہ ان کی سند میں موسیٰ بن عبیدہ ضعیف راوی ہے۔ (ارواء الغلیل: ۱۳۸۲، میزان الاعتدال: ۲۱۳/۴) ...... امام مالک کے فتویٰ پر یہ اعتراض یقیناً ہو سکتا ہے کہ یہاں انھوں نے بدل کتابت کو قرض سے تشبیہ دے کر نقد سودا کرنے کا فتویٰ دیا ہے، حالانکہ گزشتہ ابواب میں انھوں نے کئی ایک مسائل میں اسے قرض شمار کرنے کی نفی کی ہے اور قرض سے الگ چیز قرار دیا ہے، لہذا اگر ان کے گزشتہ فتووں کا لحاظ کریں تو بلاشبہ مکاتب غلام کو ادھار بیچنا جائز ثابت ہوتا ہے کیونکہ جب بدل کتابت کو قرض نہیں کہیں گے تو قرض کی قرض کے بدلے خرید وفروخت لازم نہ آئے گی۔ واللہ اعلم! اسی طرح خریدار جس کسی چیز کے بدلے میں چاہے اسے خرید سکتا ہے خواہ مکاتبت بھی اسی چیز پر ہوئی ہو کیونکہ حقیقت میں مکاتبت محض ایک معاہدہ ہے اور بدل کتابت بھی معاہدے کی ایک شق ہے اور یہ معاہدہ پورا بھی ہو سکتا ہے اور ختم بھی ہو سکتا ہے، لہذا یہ ایک معنوی چیز ہے، جب اس جانب کوئی چیز موجود ہی نہیں تو پھر ان احتیاطوں کی بھی کوئی ضرورت نہیں۔ یہی وجہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدہ بریرہ رضی اللہ عنہا کے معاملے میں ایسی کوئی پابندی نہیں لگائی تھی، حالانکہ یہ واضح ہو چکا تھا کہ سیدہ بریرہ رضی اللہ عنہا کے مالکوں نے نو اوقیہ چاندی پر مکاتبت کی تھی اور سیدہ عائشہ رضی اللہ عنہا نے چاندی دے کر خریدنے ہی کا پیغام بھیجا تھا جسے رسول اللہ صلی اللہ علیہ وسلم نے درست قرار دیا۔ (بخاری: ۲۱۶۸، ۲۵۶۵) اگر امام مالک رحمہ اللہ کی مذکورہ بالا احتیاطوں کو دیکھیں تو یہ معاملہ درست نہیں ہو سکتا کہ جب دونوں جانب چاندی ہو تو اس میں ادھار حرام ہے، حالانکہ رسول اللہ صلی اللہ علیہ وسلم اس سیدہ بریرہ رضی اللہ عنہا والے معاملے کو حلال قرار دے رہے ہیں۔ تو معلوم ہوا کہ مکاتب کے معاملے میں ایسی صورت بنتی ہی نہیں، اس میں زر کتابت کے بدلے قیمت نہیں ہوتی، بلکہ غلام ہی کے ساتھ قیمت کا تبادلہ ہوتا ہے۔","قَالَ مَالِكٌ: أَحْسَنُ مَا سَمِعْتُ فِي الْمُكَاتَبِ: أَنَّهُ إِذَا بِيعَ كَانَ أَحَقَّ بِاشْتِرَاءِ كِتَابَتِهِ مِمَّنِ اشْتَرَاهَا، إِذَا قَوِيَ أَنْ يُؤَدِّيَ إِلَى سَيِّدِهِ الثَّمَنَ الَّذِي بَاعَهُ بِهِ نَقْداً، وَذَلِكَ أَنَّ اشْتِرَاءَهُ نَفْسَهُ عَتَاقَةٌ، وَالْعَتَاقَةُ تُبَدَّأُ عَلَى مَا كَانَ مَعَهَا مِنَ الْوَصَايَا، وَإِنْ بَاعَ بَعْضُ مَنْ كَاتَبَ الْمُكَاتَبَ نَصِيبَهُ مِنْهُ، فَبَاعَ نِصْفَ الْمُكَاتَبِ أَوْ ثُلُثَهُ أَوْ رُبُعَهُ أَوْ سَهْماً مِنْ أَسْهُمِ الْمُكَاتَبِ، فَلَيْسَ لِلْمُكَاتَبِ فِيمَا بِيعَ مِنْهُ شُفْعَةٌ، وَذَلِكَ أَنَّهُ يَصِيرُ بِمَنْزِلَةِ الْقَطَاعَةِ، وَلَيْسَ لَهُ أَنْ يُقَاطِعَ بَعْضَ مَنْ كَاتَبَهُ إِلَّا بِإِذْنِ شُرَكَائِهِ، وَأَنَّ مَا بِيعَ مِنْهُ لَيْسَتْ لَهُ بِهِ حُرْمَةٌ تَامَّةٌ، وَأَنَّ مَالَهُ مَحْجُورٌ عَنْهُ، وَأَنَّ اشْتِرَاءَهُ بَعْضَهُ يُخَافُ عَلَيْهِ مِنْهُ الْعَجْزُ لِمَا يَذْهَبُ مِنْ مَالِهِ، وَلَيْسَ ذَلِكَ بِمَنْزِلَةِ اشْتِرَاءِ الْمُكَاتَبِ نَفْسَهُ كَامِلاً، إِلَّا أَنْ يَأْذَنَ لَهُ مَنْ بَقِيَ لَهُ فِيهِ كِتَابَةٌ، فَإِنْ أَذِنُوا لَهُ كَانَ أَحَقَّ بِمَا بِيعَ مِنْهُ.","امام مالک رحمہ اللہ نے فرمایا: سب سے اچھی بات جو میں نے مکاتب کے متعلق سنی ہے، یہ ہے کہ جب اس کے زر کتابت کو بیچا جانے لگے تو وہ اپنے خریدار کی نسبت اپنے بدل کتابت کو خریدنے کا زیادہ حق دار ہے جب اسے یہ قدرت حاصل ہو کہ اپنے آقا کو وہ قیمت نقد ادا کر دے جس کے عوض وہ اسے بیچنا چاہتا ہے اور یہ (اس کا زیادہ استحقاق) اس وجہ سے ہے کہ بلاشبہ اس کا خود کو خریدنا (دراصل اپنے آپ کو) آزاد کرنا ہے اور یقیناً آزاد کرنے کا عمل ان تمام وصیتوں پر مقدم رکھا جاتا ہے جو اس کے ہمراہ ہوں (اور شریعت بھی غلام آزاد کرنے کی بہت ترغیب دیتی ہے، تو اب اس کا آقا اپنا مقرر کیا ہوا بدل کتابت کسی سے وصول کرنے کی بجائے اسی مکاتب غلام سے لے لے تو غلام فوراً آزاد ہو جائے گا اور یہ بہتر ہے اس سے کہ اس کی گردن کسی اور شخص کے قبضے میں جائے، چنانچہ اگر اس کا آقا اسے کسی کے ہاتھ بھی دے تو یہ غلام حق شفعہ رکھتا ہے اور عدالت کی طرف رجوع کر کے خود نقد رقم ادا کر کے خود کو آزاد کروا سکتا ہے۔ بہر حال یہ استحقاق اور ترجیح صرف اس وقت ہے جب اس کا ایک ہی آقا ہو اور اسے پورے کا پورا بیچ رہا ہو یا کئی آقا ہوں اور اکٹھے مل کر اسے مکمل فروخت کر رہے ہوں) اور اگر مکاتب سے مکاتبت کرنے والوں میں سے کوئی ایک آقا اس غلام میں سے اپنا حصہ بیچ دے، چنانچہ وہ مکاتب غلام کا نصف یا تہائی یا چوتھائی یا مکاتب کے حصوں میں سے کوئی حصہ بیچ ڈالے تو مکاتب کے لیے اپنے اس حصے میں حق شفعہ نہیں ہے جو اس میں سے بیچ دیا گیا ہے اس لیے کہ بے شک یہ صورت تو قطاعت والی بن جاتی ہے اور مکاتب غلام کے لیے جائز نہیں کہ اپنے ساتھ مکاتبت کرنے والے افراد (آقاؤں) میں سے کسی ایک کے ساتھ قطاعت کر لے (جیسا کہ پچھلے باب میں تفصیل سے گزر چکا ہے)، مگر اس کے شریکوں (باقی آقاؤں) کی اجازت کے ساتھ (ایسا کر سکتا ہے، آگے امام مالک رحمہ اللہ کچھ وجوہات بیان کر رہے ہیں جن کی بنا پر وہ کسی ایک آقا کے ساتھ قطاعت نہیں کر سکتا کہ نقد رقم دے کر اس کی طرف سے اپنا ایک حصہ آزاد کروا لے، چنانچہ وہ فرماتے ہیں:) بے شک اس کا جو حصہ بیچا گیا ہے اس کی وجہ سے اسے حرمت تامہ (آزادی کی مکمل حرمت) بھی حاصل نہیں ہوئی (اور اب بھی اس پر غلاموں ہی کے احکام لاگو ہوتے ہیں) اور یقیناً اس کا مال بھی اس (کے تصرف) سے روکا گیا ہے اور بلاشبہ اس کے اپنا کچھ حصہ خرید لینے کی بنا پر اس پر یہ خطرہ ہے کہ وہ (اپنے بدل کتابت کو ادا کرنے سے) عاجز آ جائے گا، اس لیے کہ اس کا مال (اس خریداری میں استعمال ہو تو اس کے ہاتھ سے) چلا جائے گا (یعنی کہیں ایسا نہ ہو کہ اپنا کچھ حصہ خریدنے کے شوق میں پیسہ صرف ہو جائے اور وہ زر کتابت کی ادائیگی سے عاجز آ کر مکمل غلامی میں واپس لوٹ جائے) اور یہ (بیان کردہ خریداری) اس خریداری کی طرح نہیں ہے جس میں مکاتب غلام خود کو مکمل خرید لیتا ہے۔ (بہر حال کسی ایک آقا سے اپنا حصہ خریدنا مکاتب غلام کے لیے درست نہیں) الا یہ کہ اسے دوسرے آقا اجازت دے دیں جن کا اس میں بدل کتابت باقی ہے، چنانچہ اگر وہ اسے اجازت دے دیں تو وہ اپنے اس حصے کا زیادہ حقدار ہوگا جو اس سے بیچا گیا ہے۔ (لہذا وہ اس میں حق شفعہ کر کے خریدا ہوا سودا باطل کر کے خود ہی اپنا وہ حصہ خرید سکتا ہے) قَالَ مَالِكٌ: لَا يَحِلُّ بَيْعُ نَجْمٍ مِنْ نُجُومِ الْمُكَاتَبِ، وَذَلِكَ أَنَّهُ غَرَرٌ، إِنْ عَجَزَ الْمُكَاتَبُ بَطَلَ مَا عَلَيْهِ، وَإِنْ مَاتَ أَوْ أَفْلَسَ وَعَلَيْهِ دُيُونٌ لِلنَّاسِ، لَمْ يَأْخُذِ الَّذِي اشْتَرَى نَجْمَهُ بِحِصَّتِهِ مَعَ غُرَمَائِهِ شَيْئاً، وَإِنَّمَا الَّذِي اشْتَرَى نَجْماً مِنْ نُجُومِ الْمُكَاتَبِ، بِمَنْزِلَةِ سَيِّدِ الْمُكَاتَبِ، فَسَيِّدُ الْمُكَاتَبِ لَا يُحَاصُّ بِكِتَابَةِ غُلَامِهِ غُرَمَاءَ الْمُكَاتَبِ، وَكَذَلِكَ الْخَرَاجُ أَيْضاً يَجْتَمِعُ لَهُ عَلَى غُلَامِهِ، فَلَا","امام مالک رحمہ اللہ نے فرمایا: مکاتب کی قسطوں میں سے کسی قسط کو بیچنا جائز نہیں کیونکہ یہ دھوکا ہے (کیونکہ خریدار کو کوئی یقین نہیں کہ غلام اسے ملے گا یا نہیں، نیز دھوکے والی خرید و فروخت شرعاً ممنوع ہے اور یہ دھوکا و فراڈ اور سراسر نقصان اس طرح ہے کہ) اگر مکاتب غلام عاجز آ جائے تو جو کچھ اس کے ذمے ہوتا ہے سب باطل ہو جاتا ہے (اور وہ ادا شدہ قسط بھی باطل ہو جاتی ہے) اور اگر وہ غلام مر جائے یا مفلس ہو جائے اور اس پر لوگوں کے قرضے ہوں تو جس شخص نے اس کی ایک قسط (رقم دے کر) خریدی تھی وہ اس يُحَاصُّ بِمَا اجْتَمَعَ لَهُ مِنَ الْخَرَاجِ غُرَمَاءَ غُلَامِهِ.","غلام کے قرض خواہوں کے ساتھ اپنے حصے کی کوئی چیز وصول نہیں کر سکتا، اور بلاشبہ مکاتب کی قسطوں میں سے کسی قسط کو خریدنے والا مکاتب غلام کے آقا کی طرح ہی ہے، چنانچہ مکاتب کا آقا اپنے غلام کی کتابت (کی رقم لینے) کے لیے اس کے قرض خواہوں کے ساتھ برابر کا حصے دار نہیں بن سکتا اور اسی طرح (غلام کی روزانہ کمائی ہوئی) آمدنی کا بھی معاملہ ہے جو آقا کے لیے غلام کے ذمے جمع ہوتی رہتی ہے تو (اس کے باوجود) وہ آقا اس کے ذمے اپنی جمع شدہ آمدنی کے لیے اپنے غلام کے قرض خواہوں کے ساتھ حصہ دار اور ساجھی نہیں بن سکتا۔","قَالَ مَالِكٌ: لَا بَأْسَ بِأَنْ يَشْتَرِيَ الْمُكَاتَبُ كِتَابَتَهُ بِعَيْنٍ أَوْ عَرْضٍ مُخَالِفٍ لِمَا كُوتِبَ بِهِ مِنَ الْعَيْنِ أَوِ الْعَرْضِ أَوْ غَيْرِ مُخَالِفٍ، مُعَجَّلٍ أَوْ مُؤَخَّرٍ.","امام مالک رحمہ اللہ نے فرمایا: اس میں کوئی حرج نہیں کہ مکاتب اپنے بدل کتابت کو کسی ایسی نقدی (سونا چاندی) یا کسی ایسے سامان کے عوض خرید لے جو اس نقدی یا سامان کے علاوہ ہو جس پر کہ اس سے کتابت کی گئی تھی یا اس کے مخالف نہ ہو (بلکہ ہم جنس نقدی یا سامان کا تبادلہ کر لے) خواہ نقد فی الفور ادا کرے یا (ادھار اور) تاخیر سے ادا کر لے۔","...... کیونکہ کتابت ’’دین صحیح‘‘ (ثابت شدہ قرض) تو ہے نہیں کہ سود لازم آئے۔","قَالَ مَالِكٌ فِي الْمُكَاتَبِ يَهْلِكُ وَيَتْرُكُ أُمَّ وَلَدٍ وَوَلَداً لَهُ صِغَاراً مِنْهَا، أَوْ مِنْ غَيْرِهَا، فَلَا يَقْوَوْنَ عَلَى السَّعْيِ، وَيُخَافُ عَلَيْهِمُ الْعَجْزُ عَنْ كِتَابَتِهِمْ، قَالَ: تُبَاعُ أُمُّ وَلَدِ أَبِيهِمْ إِذَا كَانَ فِي ثَمَنِهَا مَا يُؤَدَّى بِهِ عَنْهُمْ جَمِيعُ كِتَابَتِهِمْ، أُمَّهُمْ كَانَتْ أَوْ غَيْرَ أُمِّهِمْ، يُؤَدَّى عَنْهُمْ وَيَعْتِقُونَ، لِأَنَّ أَبَاهُمْ كَانَ لَا يُمْنَعُ بَيْعَهَا إِذَا خَافَ الْعَجْزَ عَنْ كِتَابَتِهِ، فَهَؤُلَاءِ إِذَا خِيفَ عَلَيْهِمُ الْعَجْزُ، بِيعَتْ أُمُّ وَلَدِ أَبِيهِمْ، فَيُؤَدَّى عَنْهُمْ ثَمَنُهَا، فَإِنْ لَمْ يَكُنْ فِي ثَمَنِهَا مَا يُؤَدَّى عَنْهُمْ، وَلَمْ تَقْوَ هِيَ وَلَا هُمْ عَلَى السَّعْيِ، رَجَعُوا جَمِيعاً رَقِيقاً لِسَيِّدِهِمْ.","امام مالک رحمہ اللہ نے اس مکاتب غلام کے متعلق فرمایا جو فوت ہو جاتا ہے اور ایک ام ولد لونڈی نیز اپنے کچھ بچے چھوڑ جاتا ہے جو اس ام ولد لونڈی سے ہوں یا کسی اور سے، چنانچہ وہ اولاد (کتابت کی ادائیگی کے لیے) محنت کرنے پر طاقت نہ رکھتی ہو اور ان کے متعلق بدل کتابت کی ادائیگی سے عاجز آ جانے کا خطرہ ہو تو امام مالک رحمہ اللہ نے فرمایا: ان کے باپ کی ام ولد لونڈی کو بیچ دیا جائے گا، بشرطیکہ اس کی قیمت میں اتنی مقدار ہو جس کے ذریعے ان سب کے سب بچوں کا بدل کتابت ہو سکے، خواہ وہ ام ولد لونڈی ان بچوں کی ماں ہی ہو یا ان کی ماں کے علاوہ ہو، (اس کی قیمت سے ان کے بدل کتابت کی) ان کی طرف سے ادائیگی کی جائے گی اور وہ سب آزاد ہو جائیں گے، اس لیے کہ (یہ ام ولد لونڈی مرنے والے مکاتب کا مال ہے اور مکاتب غلام اپنے مال ہی سے زر کتابت ادا کرتا ہے چنانچہ) ان کا باپ جب اپنی کتابت کی ادائیگی سے عاجز آنے کا خطرہ محسوس کرتا تو اسے اس (ام ولد لونڈی) کو بیچنے سے روکا نہیں جا سکتا تھا، لہذا (اب بھی اسے فروخت کر کے) ان بچوں کی طرف سے ادائیگی کی جائے گی، (تاکہ ان بچوں کو تو آزادی کی نعمت ملے لیکن پھر اگر اس کی قیمت اس قدر نہ ہو کہ سب کی طرف سے ادائیگی کی جا سکے اور وہ ام ولد لونڈی اور بچے محنت کرنے پر بھی قدرت نہیں رکھتے تو وہ سب عاجز شمار ہوں گے اور) سب کے سب اپنے آقا کی غلامی میں لوٹ جائیں گے۔","قَالَ مَالِكٌ: الْأَمْرُ عِنْدَنَا فِي الَّذِي يَبْتَاعُ كِتَابَةَ الْمُكَاتَبِ، ثُمَّ يَهْلِكُ الْمُكَاتَبُ قَبْلَ أَنْ يُؤَدِّيَ كِتَابَتَهُ: أَنَّهُ يَرِثُهُ الَّذِي اشْتَرَى كِتَابَتَهُ، وَإِنْ عَجَزَ فَلَهُ رَقَبَتُهُ، وَإِنْ أَدَّى الْمُكَاتَبُ كِتَابَتَهُ إِلَى الَّذِي اشْتَرَاهَا وَعَتَقَ، فَوَلَاؤُهُ لِلَّذِي عَقَدَ كِتَابَتَهُ، لَيْسَ لِلَّذِي اشْتَرَى كِتَابَتَهُ مِنْ وَلَائِهِ شَيْءٌ.","امام مالک رحمہ اللہ نے فرمایا: ہمارے ہاں یہ حکم متفقہ ہے، اس شخص کے متعلق جو مکاتب غلام کی کتابت کو خرید لیتا ہے، پھر مکاتب (اس دوسرے آقا کو) اپنا بدل کتابت ادا کرنے سے پہلے ہی مر جاتا ہے تو بلاشبہ اس (کے مال) کا وارث وہی بنے گا جس نے اسے خرید لیا تھا اور اگر (وہ مرنے کی بجائے عاجز آ جاتا ہے تو اس (خریدار) کے لیے اس کی گردن (کی ملکیت) ہے (یعنی مکاتب کی مکاتبت ختم ہو جائے گی اور یہ خریدار آقا اسے بیچنا چاہے تو بیچ کر رقم کما سکتا ہے) اور اگر مکاتب اپنا زر کتابت اس شخص کو ادا کر دے جس نے اس کی کتابت کو خرید لیا تھا اور اسی (دوسرے خریدار آقا) کی طرف سے (اسے) آزادی حاصل ہوئی ہو تو اس کی ولاء اس (پہلے آقا) سے (ثابت) ہوگی جس نے اس سے عقد کتابت کیا تھا اور جس (دوسرے آقا) نے اس کی کتابت خریدی تھی اس کے لیے اس کی ولاء میں سے کچھ بھی نہ ہوگا۔","...... یہ صورت سیدہ بریرہ رضی اللہ عنہا کے معاملے جیسی نہیں ہے کیونکہ وہاں دوسرے آقا (سیدہ عائشہ رضی اللہ عنہا) نے مکاتب غلام (سیدہ بریرہ رضی اللہ عنہا) سے تو کچھ بھی وصول نہیں کیا تھا بلکہ خرید کر آزاد کر دیا تھا جبکہ مذکورہ فتویٰ والی صورت میں دوسرا آقا اس مکاتب غلام سے وہ بدل کتابت وصول کرتا رہا ہے جو پہلے آقا نے طے کیا تھا۔"],"425":["§خلاصۃ الباب","اس باب میں ایک مقطوع روایت (اثر تابعی) ہے جو سنداً ضعیف ہے، نیز امام مالک رحمہ اللہ کے تین فتاویٰ جات بھی اس میں مذکور ہیں۔"],"426":["§خلاصۃ الباب","اس باب میں ایک مقطوع روایت (اثر تابعی) ہے جو سنداً صحیح ہے، نیز اس باب میں امام مالک رحمہ اللہ کے دو فتاویٰ بھی مذکور ہیں۔"],"427":["§خلاصۃ الباب","اس باب میں ایک مقطوع روایت یعنی اثر تابعی ہے جو سنداً ضعیف ہے، نیز امام مالک رحمہ اللہ کے تین فتاویٰ جات بھی مذکور ہیں۔"],"428":["§خلاصۃ الباب","اس باب میں روایت تو کوئی بھی نہیں البتہ امام مالک رحمہ اللہ کے تین فتاویٰ مذکور ہیں۔","حَدَّثَنِي مَالِكٌ فِي رَجُلٍ كَاتَبَ عَبْدَهُ بِذَهَبٍ أَوْ وَرِقٍ، وَاشْتَرَطَ عَلَيْهِ فِي كِتَابَتِهِ سَفَراً أَوْ خِدْمَةً أَوْ ضَحِيَّةً : إِنَّ كُلَّ شَيْءٍ مِنْ ذَلِكَ سَمَّى بِاسْمِهِ، ثُمَّ قَوِيَ الْمُكَاتَبُ عَلَى أَدَاءِ نُجُومِهِ كُلِّهَا قَبْلَ مَحِلِّهَا . قَالَ : إِذَا أَدَّى نُجُومَهُ كُلَّهَا، وَعَلَيْهِ هَذَا الشَّرْطُ عَتَقَ فَتَمَّتْ حُرْمَتُهُ، وَنُظِرَ إِلَى مَا شَرَطَ عَلَيْهِ مِنْ خِدْمَةٍ أَوْ سَفَرٍ أَوْ مَا أَشْبَهَ ذَلِكَ ، مِمَّا يُعَالِجُهُ هُوَ بِنَفْسِهِ ، فَذَلِكَ مَوْضُوعٌ عَنْهُ ، لَيْسَ لِسَيِّدِهِ فِيهِ شَيْءٌ، وَمَا كَانَ مِنْ ضَحِيَّةٍ أَوْ كِسْوَةٍ أَوْ شَيْءٍ يُؤَدِّيهِ، فَإِنَّمَا هُوَ بِمَنْزِلَةِ الدَّنَانِيرِ وَالدَّرَاهِمِ، يُقَوَّمُ ذَلِكَ عَلَيْهِ فَيَدْفَعُهُ مَعَ نُجُومِهِ، وَلَا يَعْتِقُ حَتَّى يَدْفَعَ ذَلِكَ مَعَ نُجُومِهِ.","امام مالک رحمہ اللہ نے اس شخص کے متعلق فرمایا جس نے سونے یا چاندی کے بدلے اپنے غلام سے مکاتبت کر لی اور عقد کتابت میں اس پر کسی سفر یا خدمت یا قربانی کی شرط لگا لی (کہ مثلاً وہ بدل کتابت کی ادائیگی کے ساتھ ساتھ فلاں کام بھی کرے گا) اور ان میں سے ہر چیز (یعنی جس کا بھی ذکر کیا تو اس) کا نام لے کر اسے متعین بھی کر دیا، پھر مکاتب غلام نے تمام قسطوں کو مقررہ مدت سے پہلے ہی اکٹھا ادا کرنے پر قوت پا لی، (تو اس بارے میں امام صاحب نے فرمایا: جب وہ اپنی ساری قسطیں اس حال میں ادا کر دے کہ اس پر یہ شرط عائد ہو تو (پھر بھی) وہ آزاد ہو جائے گا اور اس کی آزادی کی) حرمت مکمل ہو جائے گی اور (پھر) اس پر لگائی گئی شرط کو دیکھا جائے گا (کہ اگر وہ) خدمت یا سفر یا ان کے مشابہ کسی چیز کی شرط ہو (جو مکاتب کو (جسمانی مشقت کے ساتھ) خود ادا کرنا پڑتی ہو تو وہ اس سے ساقط ہو جائے گی اور اس (کے پورا کرانے) میں اس کے آقا کے لیے کچھ بھی (حق) نہ ہوگا اور وہ شرط جو قربانی کرے یا کپڑے پہنانے یا کسی ایسی چیز کی ہو جسے وہ مکاتب (مال کی صورت میں) اس آقا کو ادا کرے گا تو بلا شبہ یہ (بدل کتابت کے) دیناروں اور درہموں کی طرح ہی ہے، (چنانچہ) اس چیز کی قیمت اس مکاتب پر (اس کے ذمے لگائی جائے گی، پھر وہ اسے بھی اپنی (کتابت والی) قسطوں کے ساتھ ہی ادا کرے گا اور وہ آزاد نہیں ہوگا یہاں تک کہ اسے بھی اپنی قسطوں کے ہمراہ ادا کر دے۔","..... الغرض جس شرط کا تعلق جسمانی عمل سے ہو وہ زر کتابت کی ادائیگی کے بعد ساقط ہو جائے گی اور جس کا تعلق مال سے ہو وہ زر کتابت ہی کا حصہ شمار ہوگی۔ ہمارے نزدیک اس بارے میں راجح موقف یہ ہے کہ غلام کی آزادی سے قبل اس پر جو شرط بھی لگائی جائے خواہ اس کا تعلق بدنی عمل سے ہو یا مال سے تو اسے آزادی کے بعد پورا کرنا لازم ہے، البتہ آزادی کے بعد شرط لگانا درست نہیں جیسا کہ پیچھے کتاب العتق کے دوسرے باب میں اس کا تذکرہ ہو چکا ہے، نیز اگر آزادی کو کسی شرط کے ساتھ معلق کیا گیا ہو تو اسے پورا کیے بغیر آزادی نہیں ملتی۔ واللہ اعلم قَالَ مَالِكٌ: الْأَمْرُ الْمُجْتَمَعُ عَلَيْهِ عِنْدَنَا الَّذِي لَا اخْتِلَافَ فِيهِ : أَنَّ الْمُكَاتَبَ بِمَنْزِلَةِ عَبْدٍ أَعْتَقَهُ سَيِّدُهُ بَعْدَ خِدْمَةِ عَشْرِ سِنِينَ، فَإِذَا هَلَكَ سَيِّدُهُ الَّذِي أَعْتَقَهُ قَبْلَ عَشْرِ سِنِينَ، فَإِنَّ مَا بَقِيَ عَلَيْهِ مِنْ خِدْمَتِهِ لِوَرَثَتِهِ، وَكَانَ وَلَاؤُهُ لِلَّذِي عَقَدَ عِتْقَهُ، وَلِوَلَدِهِ مِنَ الرِّجَالِ أَوِ الْعَصَبَةِ .","امام مالک رحمہ اللہ نے فرمایا: وہ حکم جس پر ہمارے ہاں اجماع ہے اور جس میں کوئی اختلاف نہیں، یہ ہے کہ یقیناً مکاتب اس غلام کی طرح ہوتا ہے جسے اس کا آقا دس سال کی خدمت کے بعد آزاد کرے (یعنی اس عام غلام کی طرح ہے جس پر یہ شرط عائد کی گئی ہو کہ دس سال خدمت کر لو گے تو آزاد ہو جاؤ گے)، پھر جب اس کا وہ آقا جس نے اسے (دس سالہ خدمت کی شرط پر) آزادی کا کہا تھا، دس سال سے پہلے ہی فوت ہو جائے تو بلاشبہ اس کی خدمت میں سے جو (عرصہ) باقی ہو وہ اس آقا کے ورثاء کے لیے ہوگا، (اب یہ غلام آقا کے ورثاء کی خدمت کرتا رہے گا) اور اس کی ولاء اس آقا کے لیے ثابت ہو گی جس نے اس کی آزادی کا عقد اور معاملہ طے کیا تھا اور پھر یہ ولاء اس کی مذکر اولاد کے لیے یا عصبہ کے لیے ہوگی۔","..... مقصد یہ ہے کہ مذکورہ مثال کی طرح مکاتب غلام کا آقا دورانِ کتابت مر جائے تو اس کی اولاد کو باقی ماندہ قسطیں ادا کر کے وہ آزاد ہو جائے گا۔","قَالَ مَالِكٌ فِي الرَّجُلِ يَشْتَرِطُ عَلَى مُكَاتِبِهِ أَنَّكَ لَا تُسَافِرُ وَلَا تَنْكِحُ وَلَا تَخْرُجُ مِنْ أَرْضِي إِلَّا بِإِذْنِي ، فَإِنْ فَعَلْتَ شَيْئاً مِنْ ذَلِكَ بِغَيْرِ إِذْنِي ، فَمَحْوُ كِتَابَتِكَ بِيَدِي . قَالَ مَالِكٌ : لَيْسَ مَحْوُ كِتَابَتِهِ بِيَدِهِ إِنْ فَعَلَ الْمُكَاتَبُ شَيْئاً مِنْ ذَلِكَ ، وَلْيَرْفَعْ سَيِّدُهُ ذَلِكَ إِلَى السُّلْطَانِ، وَلَيْسَ لِلْمُكَاتَبِ أَنْ يَنْكِحَ وَلَا يُسَافِرَ وَلَا يَخْرُجَ مِنْ أَرْضِ سَيِّدِهِ إِلَّا بِإِذْنِهِ ، اشْتَرَطَ ذَلِكَ أَوْ لَمْ يَشْتَرِطْهُ ، وَذَلِكَ أَنَّ الرَّجُلَ يُكَاتِبُ عَبْدَهُ بِمِئَةِ دِينَارٍ ، وَلَهُ أَلْفُ","امام مالک رحمہ اللہ نے اس آدمی کے متعلق فرمایا جو اپنے مکاتب غلام پر یہ شرط لگا لیتا ہے کہ نہ تم سفر کرو گے، نہ نکاح کرو گے اور نہ میری زمین سے نکلو گے۔ الا یہ کہ میں تمھیں اجازت دوں، چنانچہ اگر تو نے ان میں سے کوئی کام میری اجازت کے بغیر کر لیا تو تیری مکاتبت کو مٹانا (اور اسے باطل قرار دینا) میرے اختیار میں ہوگا، امام مالک رحمہ اللہ نے فرمایا کہ اگر مکاتب ان کاموں میں سے کوئی کام کر لے تو اس کی کتابت کو باطل قرار دینا اس کے اختیار میں نہیں ہوگا، (کیونکہ یہ شرط ہی باطل ہے اور مکاتبت کے تقاضے ہی کے برعکس ہے۔ مکاتبت کا تقاضا آزادی ہے اور اس کی شرط کا دِينَارٍ أَوْ أَكْثَرُ مِنْ ذَلِكَ، فَيَنْطَلِقُ فَيَنْكِحُ الْمَرْأَةَ، فَيُصْدِقُهَا الصَّدَاقَ الَّذِي يُجْحِفُ بِمَالِهِ، وَيَكُونُ فِيهِ عَجْزُهُ، فَيَرْجِعُ إِلَى سَيِّدِهِ عَبْداً لَا مَالَ لَهُ، أَوْ يُسَافِرُ فَتَحِلُّ نُجُومُهُ وَهُوَ غَائِبٌ، فَلَيْسَ ذَلِكَ لَهُ، وَلَا عَلَى ذَلِكَ كَاتَبَهُ، وَذَلِكَ بِيَدِ سَيِّدِهِ إِنْ شَاءَ أَذِنَ لَهُ فِي ذَلِكَ، وَإِنْ شَاءَ مَنَعَهُ .","تقاضا غلامی ہے، لہذا مکاتبت ثابت ہو جائے گی اور اس کی شرط باطل قرار پائے گی جس طرح کہ کوئی شخص عقد کتابت میں یہ شرط لگا لے کہ تیری ولاء میری بجائے فلاں شخص کے لیے ہے تو چونکہ یہ شرط بھی کتابت کے تقاضے کے خلاف ہے اس لیے باطل ہے)، اور اس کے آقا کو چاہیے کہ یہ معاملہ حاکم کے پاس لے کر جائے، (نیز یہ شرطیں لگانا تو ایک عبث اور بے کار کام ہے کیونکہ یہ کام تو پہلے ہی سے مکاتب کے لیے آقا کی اجازت کے بغیر ممنوع ہیں، سو امام مالک رحمہ اللہ فرماتے ہیں): اور مکاتب کے لیے یہ درست نہیں کہ آقا کی اجازت کے بغیر نکاح کرے، نہ وہ سفر کرے اور نہ ہی اپنے آقا کی زمین سے نکلے، خواہ وہ ان کاموں کی شرط لگائے یا نہ لگائے اور یہ (ممانعت) اس وجہ سے ہے کہ (مثلاً) آدمی اپنے غلام سے سو دینار پر مکاتبت کر لے اور اس وقت غلام کے پاس ہزار یا اس سے بھی زیادہ دینار ہوں، پھر وہ مکاتب جا کر کسی عورت سے نکاح کر لے اور اسے اس قدر حق مہر دے دے جو اس کے مال کو برباد کر دے (اور اس غلام کے پاس کچھ بھی باقی نہ بچے) اور اس عمل میں اس کا عاجز ہونا واقع ہو جائے تو وہ دوبارہ اپنے آقا کی طرف (کامل) غلام بن کر اس حال میں لوٹے گا کہ اس کے پاس کچھ بھی مال نہ ہوگا (یوں اس نے اپنا بھی نقصان کیا کہ دوبارہ غلام بن گیا اور آقا کا بھی نقصان کیا کہ ولاء کی وجہ سے اسے جو مال مل سکتا تھا وہ برباد کر دیا) یا وہ (مثلاً) سفر میں جاتا ہے تو اس کی قسطوں کی ادائیگی (کی تاریخ) آ جاتی ہے لیکن وہ غائب ہوتا ہے (اور اس میں بھی آقا کا حرج ہے) لہذا اس مکاتب کے لیے یہ کام جائز ہی نہیں اور نہ اس نے ان کاموں پر مکاتبت کی ہے اور یہ کام اس کے آقا کے اختیار میں ہیں، اگر وہ چاہے تو مکاتب غلام کو ان کی اجازت دے دے اور اگر چاہے تو اسے روک دے۔"],"429":["§خلاصۃ الباب","اس باب میں امام مالک رحمہ اللہ کے سات فتاویٰ جات مذکور ہیں۔","قَالَ مَالِكٌ : إِنَّ الْمُكَاتَبَ إِذَا أَعْتَقَ عَبْدَهُ، إِنَّ ذَلِكَ غَيْرُ جَائِزٍ لَهُ إِلَّا بِإِذْنِ سَيِّدِهِ ، فَإِنْ أَجَازَ ذَلِكَ سَيِّدُهُ لَهُ ، ثُمَّ عَتَقَ الْمُكَاتَبُ ، كَانَ وَلَاؤُهُ لِلْمُكَاتَبِ، وَإِنْ مَاتَ الْمُكَاتَبُ قَبْلَ","امام مالک رحمہ اللہ نے فرمایا: بے شک مکاتب غلام جب اپنے کسی غلام کو آزاد کرنا چاہے تو بلاشبہ یہ کام اس کے لیے جائز نہیں ہے، مگر اپنے آقا کی اجازت کے ساتھ (وہ ایسا کر سکتا ہے) پھر اگر اس مکاتب کا آقا اس کو اس کے حق میں أَنْ يُعْتَقَ، كَانَ وَلَاءُ الْمُعْتَقِ لِسَيِّدِ الْمُكَاتَبِ، وَإِنْ مَاتَ الْمُعْتَقُ قَبْلَ أَنْ يُعْتَقَ الْمُكَاتَبُ وَرِثَهُ سَيِّدُ الْمُكَاتَبِ .","جائز قرار دے دے، پھر یہ مکاتب غلام (خود بھی اپنے آقا سے) آزاد ہو جائے تو اس (مکاتب غلام کے غلام) کی ولاء مکاتب کے لیے ہوگی، اور اگر وہ مکاتب غلام آزادی پانے سے قبل ہی مر جائے تو اس (مکاتب غلام کے غلام) کی ولاء مکاتب کے آقا کے لیے ہوگی اور اگر وہ آزاد کیا ہوا غلام مکاتب کے آزاد کیے جانے سے پہلے مر جائے تو بھی مکاتب کا آقا ہی اس کا وارث بنے گا۔","..... مقصد یہ ہے کہ مکاتب کو اپنا غلام آزاد کرنے کا فائدہ تب پہنچے گا جب اسے خود بھی آزادی ملے گی چنانچہ اگر مکاتب کی آزادی سے پہلے مکاتب کو یا اس کے آزاد کردہ غلام کو موت نے آلیا تو سارا فائدہ مکاتب کے آقا کو حاصل ہوگا .... اگر مکاتب غلام خود آزاد ہو کر اپنے غلام کو آزاد کرتا تو یہ صورت واضح ہی تھی، اس لیے اس کا ذکر نہیں کیا کیونکہ اس صورت میں یقیناً مکاتب ہی اس کی ولاء کا وارث بنتا ہے، ہاں اگر یوں ہو کہ مکاتب آزاد ہو جائے، پھر وہ اپنے غلام کو آزاد کرے، پھر مکاتب مر جائے، پھر غلام بھی مر جائے تو جس طرح مکاتب کی ولاء اس کے آقا کو ملے گی اسی طرح اس غلام کی وراثت بھی مکاتب کے آقا کو مل جائے گی۔ کیونکہ وہ اس غلام کو آزاد کرنے والے مکاتب کا آزاد کرنے والا آقا ہے۔","قَالَ مَالِكٌ : وَكَذَلِكَ أَيْضاً لَوْ كَاتَبَ الْمُكَاتَبُ عَبْداً ، فَعَتَقَ الْمُكَاتَبُ الآخَرُ قَبْلَ سَيِّدِهِ الَّذِي كَاتَبَهُ ، فَإِنَّ وَلَاءَهُ لِسَيِّدِ الْمُكَاتَبِ، مَا لَمْ يَعْتِقِ الْمُكَاتَبُ الْأَوَّلُ الَّذِي كَاتَبَهُ ، فَإِنْ عَتَقَ الَّذِي كَاتَبَهُ رَجَعَ إِلَيْهِ وَلَاءُ مُكَاتَبِهِ الَّذِي كَانَ عَتَقَ قَبْلَهُ ، وَإِنْ مَاتَ الْمُكَاتَبُ الْأَوَّلُ قَبْلَ أَنْ يُؤَدِّيَ ، أَوْ عَجَزَ عَنْ كِتَابَتِهِ وَلَهُ وَلَدٌ أَحْرَارٌ ، لَمْ يَرِثُوا وَلَاءَ مُكَاتَبِ أَبِيهِمْ ، لَأَنَّهُ لَمْ يَثْبُتْ لِأَبِيهِمُ الْوَلَاءُ ، وَلَا يَكُونُ لَهُ الْوَلَاءُ حَتَّى يَعْتِقَ.","امام مالک رحمہ اللہ نے فرمایا: اور اسی طرح یہ صورت بھی ہے کہ اگر مکاتب اپنے غلام سے مکاتبت کر لے، پھر دوسرا مکاتب اپنے اس آقا سے پہلے آزاد ہو جائے جس نے اس سے کتابت کی ہے تو بلاشبہ اس (مکاتب کے مکاتب) کی ولاء مکاتب کے آقا کے لیے ثابت رہے گی جب تک کہ پہلا مکاتب آزاد نہ ہو جائے جس نے اس (دوسرے مکاتب) سے کتابت کی تھی، چنانچہ اگر وہ (پہلا) جس نے اس (دوسرے) سے مکاتبت کی تھی آزاد ہو جائے تو اسی کی طرف اپنے اس مکاتب کی ولاء لوٹ آئے گی جو کہ اس سے پہلے آزاد ہو چکا تھا۔ اور اگر پہلا مکاتب (اپنا زر کتابت) ادا کرنے سے پہلے فوت ہو جائے یا اپنے بدل کتابت سے عاجز آجائے اور اس کے آزاد بچے موجود ہوں تو بھی وہ اپنے باپ (پہلے مکاتب) کے مکاتب کے وارث نہ ہوں گے کیونکہ (ان کا باپ غلامی کی حالت میں مرا تھا یا پھر دوبارہ کامل غلام بن گیا تھا اس لیے) ان کے باپ کے لیے (اپنے آزاد کردہ یعنی دوسرے مکاتب غلام کی) ولاء ثابت ہی نہ ہوسکی اور اس کے لیے ولاء ثابت نہیں ہو سکتی یہاں تک کہ وہ آزاد ہو جائے۔","..... الغرض ولاء اسی کو ملتی ہے جو آزاد ہو اور ولاء اسی کی نسل میں منتقل ہو سکتی ہے جس کے لیے پہلے خود ثابت ہو جائے۔","قَالَ مَالِكٌ فِي الْمُكَاتَبِ يَكُونُ بَيْنَ الرَّجُلَيْنِ، فَيَتْرُكُ أَحَدُهُمَا لِلْمُكَاتَبِ الَّذِي لَهُ عَلَيْهِ وَيَشِحُّ الْآخَرُ ، ثُمَّ يَمُوتُ الْمُكَاتَبُ وَيَتْرُكُ مَالاً . قَالَ مَالِكٌ : يَقْضِى الَّذِي لَمْ يَتْرُكْ لَهُ شَيْئاً مَا بَقِيَ لَهُ عَلَيْهِ ، ثُمَّ يَقْتَسِمَانِ الْمَالَ كَهَيْئَتِهِ لَوْ مَاتَ عَبْداً ، لأَنَّ الَّذِي صَنَعَ لَيْسَ بِعَتَاقَةٍ ، وَإِنَّمَا تَرَكَ مَا كَانَ لَهُ عَلَيْهِ.","امام مالک رحمہ اللہ نے اس مکاتب غلام کے متعلق فرمایا جو دو آدمیوں کے درمیان مشترک ہو، پھر ان میں سے ایک مکاتب کے حق میں وہ (بدل کتابت) چھوڑ دیتا ہے جو اس کا اس پر تھا اور دوسرا مالک بخل وحرص سے کام لیتا ہے (اور اپنا حق نہیں چھوڑتا)، پھر مکاتب غلام فوت ہو جاتا ہے اور کچھ مال بھی چھوڑ جاتا ہے، تو امام مالک رحمہ اللہ نے فرمایا: (سب سے پہلے) اس (مالک کے حق) کی ادائیگی کی جائے گی جس نے مکاتب کے لیے کچھ بھی نہیں چھوڑا تھا (اور کچھ بھی معاف نہ کیا تھا) اس حصے کو (اس کے حوالے کیا جائے گا) جو اس کا اس کے ذمے باقی تھا، پھر دونوں آقا مال (مکاتب غلام کے ترکہ) کو اسی صورت کی طرح (برابر برابر) تقسیم کر لیں گے کہ جب وہ (مکاتب مکمل) غلامی کی حالت میں مرتا، اس لیے کہ بے شک وہ کام جو (اپنا حق معاف کرنے والے) اس آقا نے کیا تھا وہ اس غلام کے حق میں آزادی نہیں بن سکتا اور بلاشبہ اس نے تو صرف اپنا وہ حق ہی چھوڑا تھا جو اس کا اس غلام کے ذمے تھا۔","..... لہذا اسے ’’عتق (آزادی) نہیں سمجھا جائے گا بلکہ ’’ترک ماله عليه‘‘ (اپنے حق کی معافی) ہی شمار کریں گے، ہاں اگر دونوں آقا اپنا اپنا حق معاف کر دیتے تو ان کا یہ عمل غلام کے حق میں آزادی شمار ہوگا۔","قَالَ مَالِكٌ : وَمِمَّا يُبَيِّنُ ذَلِكَ : أَنَّ الرَّجُلَ إِذَا مَاتَ وَتَرَكَ مُكَاتَباً ، وَتَرَكَ بَنِينَ رِجَالاً وَنِسَاءً ، ثُمَّ أَعْتَقَ أَحَدُ الْبَنِينَ نَصِيبَهُ مِنَ الْمُكَاتَبِ : إِنَّ ذَلِكَ لَا يُثْبِتُ لَهُ مِنَ الْوَلَاءِ شَيْئاً، وَلَوْ كَانَتْ عَتَاقَةً لَثَبَتَ الْوَلَاءُ لِمَنْ أَعْتَقَ مِنْهُمْ مِنْ رِجَالِهِمْ وَنِسَائِهِمْ.","امام مالک رحمہ اللہ نے فرمایا: اور ان دلائل میں سے جو اس مسئلے کو واضح کرتے ہیں ایک یہ ہے کہ بے شک ایک آدمی جب مر گیا اور ایک مکاتب غلام چھوڑ گیا اور اپنے بیٹے اور بیٹیاں بھی چھوڑ گیا، پھر بیٹوں میں سے ایک نے مکاتب غلام سے اپنا حصہ آزاد کر دیا تو بلاشبہ یہ اپنے حصے کو آزاد کرنے کا عمل اس کے لیے ولاء میں سے کچھ بھی ثابت نہ کر سکے گا اور اگر یہ عمل ’’آزادی‘‘ شمار ہوتا تو ولاء ان سب بیٹوں اور بیٹیوں میں سے صرف اس کے لیے ثابت ہوتی جس نے آزاد کیا ہوتا۔","..... لیکن ایسا نہیں ہوا اور سب بیٹوں اور بیٹیوں کے لیے ولاء ثابت ہوئی، کیونکہ مکاتب غلام کو ابھی آزادی نہیں ملی تھی اس لیے وہ میت کے ترکہ کی صورت میں ساری اولاد میں تقسیم ہوا۔ اس طرح کہ باپ کے مقرر کردہ زر کتابت میں بیٹی بیٹیاں اپنے اپنے حصوں کے مطابق حق دار ٹھہرے اور وہ مکاتب اب باپ کی بجائے اس اولاد کو بدل کتابت ادا کرے گا اور ساری اولاد کا مشترکہ غلام قرار پائے گا اور تمام اس کی ولاء میں شریک ہوں گے، الغرض مشترکہ ملکیت رکھنے والوں میں سے کوئی ایک اگر اپنا حصہ آزاد کر دے یا مکاتب بنا دے تو یہ ’’اپنے حق کی معافی‘‘ تو شمار ہوگا لیکن غلام کی ’’آزادی‘‘ نہیں سمجھا جائے گا۔","قَالَ مَالِكٌ : وَمِمَّا يُبَيِّنُ ذَلِكَ أَيْضاً : أَنَّهُمْ إِذَا أَعْتَقَ أَحَدُهُمْ نَصِيبَهُ، ثُمَّ عَجَزَ الْمُكَاتَبُ لَمْ يُقَوَّمْ عَلَى الَّذِي أَعْتَقَ نَصِيبَهُ مَا بَقِيَ مِنَ الْمُكَاتَبِ، وَلَوْ كَانَتْ عَتَاقَةً قُوِّمَ عَلَيْهِ حَتَّى يَعْتِقَ فِي مَالِهِ ، كَمَا قَالَ رَسُولُ اللهِ صلى الله عليه وسلم : مَنْ أَعْتَقَ شِرْكاً لَهُ فِي عَبْدٍ ، قُوِّمَ عَلَيْهِ قِيمَةَ الْعَدْلِ ، فَإِنْ لَمْ يَكُنْ لَهُ مَالٌ ، عَتَقَ مِنْهُ مَا عَتَقَ -","امام مالک رحمہ اللہ نے فرمایا: اور اسے واضح کرنے والی ایک دلیل یہ ہے کہ بے شک ان میں سے کوئی ایک جب اپنا حصہ آزاد کر دے، پھر مکاتب غلام عاجز آجائے تو جس نے اپنا حصہ آزاد کیا تھا اس کے ذمے مکاتب کے باقی ماندہ حصے کی قیمت نہیں لگائی جائے گی۔ اگر یہ (ایک حصے کی آزادی کا عمل غلام کے حق میں مکمل) آزادی شمار ہوتا تو اس (آزاد کرنے والے) پر غلام کی قیمت لگا دی جاتی، یہاں تک کہ وہ اس کے مال میں سے مکمل آزاد ہو جاتا جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «مَنْ اَعْتَقَ شِرْكًا لَهُ فِي عَبْدٍ قُوِّمَ عَلَيْهِ قِيْمَةَ الْعَدْلِ فَإِنْ لَّمْ يَكُنْ لَهُ مَالٌ عَتَقَ مِنْهُ مَا عَتَقَ» جس شخص نے کسی غلام میں اپنے حصے کو آزاد کر دیا تو اس پر اس کی انصاف والی قیمت لگائی جائے گی (بشرطیکہ اس کے پاس باقی ماندہ حصوں کے بقدر مال ہو، پھر اگر اس کے پاس مال نہ ہو تو اس سے صرف وہی حصہ آزاد ہوا جو (اس ایک کی طرف سے) آزاد ہوا ہو۔‘‘","..... یعنی عام غلاموں میں تو ایسا ہی ہوتا ہے کہ ایک شریک نے اپنا حصہ آزاد کیا تو باقی ماندہ حصے اس کے ذمے پڑ جاتے ہیں جس وقت کہ وہ وسعت رکھتا ہو لیکن مکاتب غلام میں ایسا نہیں ہوتا، اس میں ایک حصہ آزاد کرنے والا محض ’’اپنا حصہ معاف کرنے والا‘‘ شمار ہوتا ہے، نہ کہ آزاد کرنے والا، لہذا اس کا عمل ترک تو ہے، ’’عتق‘‘ نہیں ہے۔","امام مالک رحمہ اللہ نے اس فتویٰ میں جس حدیث کا حوالہ دیا ہے، اس مفہوم کی روایت پیچھے کتاب العتق کے آغاز میں گزر چکی ہے، دیکھئے موطا امام مالک، حدیث: ۱۲۶۷۔","قَالَ : وَمِمَّا يُبَيِّنُ ذَلِكَ أَيْضاً أَنَّ مِنْ سُنَّةِ","امام مالک رحمہ اللہ نے فرمایا: اور اس کی وضاحت کرنے والے الْمُسْلِمِينَ الَّتِي لَا اخْتِلَافَ فِيهَا : أَنَّ مَنْ أَعْتَقَ شِرْكاً لَهُ فِي مُكَاتَبٍ، لَمْ يُعْتَقْ عَلَيْهِ فِي مَالِهِ، وَلَوْ عَتَقَ عَلَيْهِ كَانَ الْوَلَاءُ لَهُ دُونَ شُرَكَائِهِ .","دلائل میں سے ایک یہ بھی ہے کہ بے شک مسلمانوں کا وہ طریقہ جس میں کوئی اختلاف نہیں، یہ ہے کہ بلاشبہ جو شخص مکاتب غلام میں موجود اپنا حصہ آزاد کر دیتا ہے تو وہ مکاتب اس کی طرف سے اس کے مال میں سے آزاد نہیں ہوتا اور اگر وہ اس کی طرف سے آزاد ہو جاتا تو ولاء باقی شریکوں کو چھوڑ کر صرف اس کے لیے ثابت ہوتی۔","..... حالانکہ یہاں اس کے آزاد کرنے کے باوجود سب شرکاء مکاتب کی ولاء تو اس ایک شخص کے لیے ہوگی جو دوسرے شرکاء کو ان کے حصوں کی عادلانہ قیمت ادا کر دے گا۔ البتہ باقی شرکاء کے اپنے اپنے حصے آزاد نہ کرنے کی صورت میں یا پہلے آزاد کرنے والے کے پاس دیگر حصص کی قیمت نہ ہونے کی شکل میں شریک رہتے ہیں، لہذا اس کا آزاد کرنا ’’عتق‘‘ (آزادی) نہیں کہلاتا بلکہ ’’اپنے حصے کا ترک‘‘ (معافی) ہی شمار ہوتا ہے۔","قَالَ : وَمِمَّا يُبَيِّنُ ذَلِكَ أَيْضاً : أَنَّ مِنْ سُنَّةِ الْمُسْلِمِينَ أَنَّ الْوَلَاءَ لِمَنْ عَقَدَ الْكِتَابَةَ، وَأَنَّهُ لَيْسَ لِمَنْ وَرِثَ سَيِّدَ الْمُكَاتَبِ مِنَ النِّسَاءِ مِنْ وَلَاءِ الْمُكَاتَبِ، وَإِنْ أَعْتَقْنَ نَصِيبَهُنَّ شَيْءٌ، إِنَّمَا وَلَاؤُهُ لِوَلَدِ سَيِّدِ الْمُكَاتَبِ الذُّكُورِ، أَوْ عَصَبَتِهِ مِنَ الرِّجَالِ.","امام مالک رحمہ اللہ نے فرمایا: اس کا ایک ثبوت یہ بھی ہے کہ بلاشبہ مسلمانوں کی یہ سنت ہے کہ بے شک ولاء صرف اس کے لیے ہوتی ہے جو عقد کتابت کرتا ہے اور (یہ بھی سنت ہے کہ) بے شک عورتوں میں سے جو جو (عورتیں) مکاتب کے آقا کی وارث بنتی ہیں ان کے لیے مکاتب کی ولاء میں سے کچھ بھی نہیں ہوتا (کیونکہ ولاء صرف عصبہ بنفسہ کو ملتی ہے اور عصبہ بنفسہ صرف مذکر ہوتے ہیں،) اگر چہ وہ (وارث بننے والی عورتیں) اپنے حصے کو آزاد کر دیں (پھر بھی وہ ولاء نہیں پاسکتیں) بلکہ بلاشبہ اس مکاتب کی ولاء تو مکاتب کے آقا کی صرف مذکر اولاد کے لیے ہوتی ہے یا ان کے لیے جو مردوں میں سے عصبہ ہوتے ہیں۔","..... اگر ان عورتوں کا اپنے حصے کو آزاد کرنا ’’عتق‘‘ (آزادی) شمار ہوتا تو یقیناً ان کو ولاء ملتی، کیونکہ اگر آزاد کرنے والی کوئی عورت ہو تو پھر مونث ہونے کے باوجود وہ ولاء پالیتی ہے لیکن مذکورہ صورت میں ان کا اپنے حصے کو آزاد کرنا ’’عتق‘‘ نہیں کہلاتا، لہذا ثابت ہوا کہ مکاتب غلام میں اپنے حصے کو چھوڑنا، معاف کرنا یا آزاد کرنا محض ’’اپنے حق کو ترک کرنا‘‘ کہلاتا ہے اور وہ ’’غلام کو آزاد کرنا‘‘ شمار نہیں ہوتا ...... یہ آخری چار مسائل اور فتاوی دراصل اس بات کے دلائل ہیں کہ مکاتب غلام کا معاملہ عام غلام کی طرح نہیں ہے اور مکاتب میں اپنے حصے کو آزاد کرنا عام غلام میں اپنا حصہ آزاد کرنا ’’آزادی‘‘ نہیں بلکہ ’’حصے کی معافی اور ترک‘‘ شمار ہوتا ہے اور اسے مجازاً آزادی کے لفظ سے تعبیر ..... کرتے ہیں کیونکہ اس کی مشابہت آزادی ہی سے ہے جبکہ حقیقت میں یہ آزادی نہیں، لہذا اس پر آزادی کے احکامات بھی مرتب نہیں ہوں گے۔"],"430":["§خلاصۃ الباب","اس باب میں کوئی روایت نہیں ہے، البتہ امام مالک رحمہ اللہ کے دو فتاوی مذکور ہیں۔","قَالَ مَالِكٌ : إِذَا كَانَ الْقَوْمُ جَمِيعاً فِي كِتَابَةٍ وَاحِدَةٍ ، لَمْ يُعْتِقْ سَيِّدُهُمْ أَحَداً مِنْهُمْ دُونَ مُوَّامَرَةِ أَصْحَابِهِ الَّذِينَ مَعَهُ فِي الْكِتَابَةِ وَرِضاً مِنْهُمْ ، وَإِنْ كَانُوا صِغَاراً ، فَلَيْسَ مُوَامَرَتُهُمْ بِشَيْءٍ، وَلَا يَجُوزُ ذَلِكَ عَلَيْهِمْ.","امام مالک رحمہ اللہ نے فرمایا: جب چند غلام ایک ہی عقد کتابت میں اکٹھے ہوں تو ان کا آقا ان میں سے کسی ایک کو، اس کے ساتھ کتابت میں موجود اس کے ساتھیوں کے مشورے اور ان کی رضا مندی کے بغیر آزاد نہیں کرسکتا، اور اگر وہ کم سن ہوں تو پھر ان کے مشورے کی کوئی حیثیت نہیں، اور (اس وقت) یہ (کسی ایک کا آزاد کرنا) ان (باقی ساتھیوں) پر (اسے ترجیح دیتے ہوئے) جائز نہ ہوگا، (وہ کمسن ساتھی رضا مند ہوں یا نہ ہوں، وہ کسی بھی صورت میں اس ایک کو آزاد نہیں کرسکتا)۔","قَالَ : وَذَلِكَ أَنَّ الرَّجُلَ رُبَّمَا كَانَ يَسْعَى عَلَى جَمِيعِ الْقَوْمِ وَيُؤَدِّى عَنْهُمْ كِتَابَتَهُمْ لِتَتِمَّ بِهِ عَتَاقَتُهُمْ ، فَيَعْمِدُ السَّيِّدُ إِلَى الَّذِي يُؤَدِّى عَنْهُمْ ، وَبِهِ نَجَاتُهُمْ مِنَ الرِّقِّ ، فَيُعْتِقُهُ فَيَكُونُ ذَلِكَ عَجْزاً لِمَنْ بَقِيَ مِنْهُمْ، وَإِنَّمَا أَرَادَ بِذَلِكَ الْفَضْلَ وَالزِّيَادَةَ لِنَفْسِهِ ، فَلاَ يَجُوزُ ذَلِكَ عَلَى مَنْ بَقِيَ مِنْهُمْ ، وَقَدْ قَالَ رَسُولُ اللهِ صلى الله عليه وسلم : لاَ ضَرَرَ وَلَا ضِرَارَ وَهَذَا أَشَدُّ الضَّرَرِ.","امام مالک رحمہ اللہ نے فرمایا: اور یہ (ممانعت) اس وجہ سے ہے کہ بے شک وہی ایک آدمی بسا اوقات (اپنے محنتی، طاقتور اور ہوشیار ہونے کی بنا پر باقی) تمام غلاموں کے لیے محنت کرتا ہے اور ان سب کی طرف سے ان کا زر کتابت ادا کر دیتا ہے تا کہ اس کے ذریعے ان تمام کی آزادی کامل ہو جائے، تو آقا اس شخص کا قصد کرتا ہے جو ان سب کی طرف سے ادائیگی کر سکتا ہے اور اس کی وجہ سے تمام کی غلامی سے نجات (کی امید) ہوتی ہے، چنانچہ وہ اسے آزاد کر دیتا ہے، پھر یہ چیز ان مکاتب غلاموں میں سے باقی سب کی عاجزی کا باعث بن جاتی ہے اور بلاشبہ اس محنتی مکاتب غلام کی آزادی سے مقصود اس پر احسان نہیں ہوتا بلکہ (وہ مالک اس کے ذریعے اپنے لیے فضیلت وزیادتی چاہتا ہے (اور زیادہ غلاموں کا مالک بن کر خود کو صاحب دولت اور مالدار دیکھنا چاہتا ہے) لہذا ان میں سے باقی غلاموں پر یہ (ایک کی ترجیح اور آزادی) جائز ہی نہیں اور یقیناً رسول اللہ صلی اللہ علیہ وسلم فرما چکے ہیں: (لَا ضَرَرَ وَلَا ضِرَارَ) ’’نہ (اسلام میں ابتداء کسی کو) نقصان دینا جائز ہے اور نہ بدلے میں کسی کو ضرر پہنچانا درست ہے اور مذکورہ آزادی باقی غلاموں کے حق میں سخت ترین ضرر اور نقصان ہے۔","یہ روایت آگے موطا امام مالک میں ’’کتابت الاقضیہ کے باب: ۲۶ میں بھی آرہی ہے، دیکھئے روایت ۱۴۴۴۔ نیز سیدنا عبادہ بن صامت رضی اللہ عنہ کی روایت سے بھی ثابت ہے۔ (ابن ماجہ: ۲۳۴۰، اس کی سند صحیح ہے) قَالَ مَالِكٌ فِي الْعَبِيدِ يُكَاتُبُونَ جَمِيعاً : إِنَّ لِسَيِّدِهِمْ أَنْ يُعْتِقَ مِنْهُمُ الْكَبِيرَ الْفَانِيَ وَالصَّغِيرَ الَّذِي لَا يُؤَدِّي وَاحِدٌ مِنْهُمَا شَيْئاً، وَلَيْسَ عِنْدَ وَاحِدٍ مِنْهُمَا عَوْنٌ وَلَا قُوَّةٌ فِي كِتَابَتِهِمْ، فَذَلِكَ جَائِزٌ لَهُ .","امام مالک رحمہ اللہ نے ان غلاموں کے متعلق فرمایا جن کو اکٹھے مکاتب بنایا جاتا ہے، (فرمایا) کہ بلاشبہ ان کے آقا کے لیے یہ جائز ہے کہ وہ ان میں سے ایسے انتہائی بوڑھے شخص کو اور ایسے بچے کو آزاد کر دے کہ جن میں سے کوئی بھی کچھ بھی (محنت کر کے) ادا نہیں کر سکتا اور نہ ان دونوں میں سے کسی کے پاس ان (باقی غلاموں) کے بدل کتابت کے لیے کوئی مدد ہے اور نہ کوئی قوت، لہذا یہ عمل آقا کے لیے جائز ہے۔"],"431":["§خلاصۃ الباب","اس باب میں امام مالک رحمہ اللہ کے دو فتاویٰ جات مذکور ہیں۔","قَالَ مَالِكٌ فِي الرَّجُلِ يُكَاتِبُ عَبْدَهُ ، ثُمَّ يَمُوتُ الْمُكَاتَبُ وَيَتْرُكُ أُمَّ وَلَدِهِ ، وَقَدْ بَقِيَتْ عَلَيْهِ مِنْ كِتَابَتِهِ بَقِيَّةٌ ، وَيَتْرُكُ وَفَاءً بِمَا عَلَيْهِ : قَالَ مَالِكٌ : إِنَّ أُمَّ وَلَدِهِ أَمَةٌ مَمْلُوكَةٌ حِينَ لَمْ يُعْتَقِ الْمُكَاتَبُ حَتَّى مَاتَ ، وَلَمْ يَتْرُكْ وَلَداً فَيُعْتَقُونَ بِأَدَاءِ مَا بَقِيَ ، فَتُعْتَقُ أُمُّ وَلَدِ أَبِيهِمْ بِعِتْقِهِمْ.","امام مالک رحمہ اللہ نے اس شخص کے متعلق فرمایا جو اپنے غلام سے کتابت کر لیتا ہے، پھر وہ مکاتب غلام مر جاتا ہے اور اپنی ام ولد لونڈی چھوڑ جاتا ہے، اس حال میں کہ اس پر اپنے زر کتابت میں سے بھی کچھ (کی ادائیگی) باقی ہو اور وہ اتنا مال بھی چھوڑ جاتا ہے جس سے اس پر واجب رقم کی مکمل ادائیگی ہو سکتی ہے، تو امام مالک رحمہ اللہ نے فرمایا: اس (مرنے والے مکاتب غلام) کی ام ولد (مکاتب کے آقا کی ملکیتی لونڈی ہو جائے گی، (لیکن یہ فیصلہ اس صورت میں ہے کہ) جب مکاتب غلام آزاد نہ ہوسکا ہو، یہاں تک کہ مر گیا اور نہ ہی وہ کوئی بچے چھوڑ کر گیا ہو کہ (اگر وہ ہوتے تو) وہ باقی ماندہ زر کتابت کی ادائیگی کر کے آزاد ہو جاتے، جس کے نتیجے میں ان کی آزادی کے ساتھ ہی ان کے باپ کی ام ولد لونڈی بھی آزاد ہو جاتی۔","چونکہ غلام کا مال آقا ہی کا شمار ہوتا ہے اور غلام کی ام ولد لونڈی بھی مال ہے، اس لیے وہ بھی اپنے آقا کے آقا ہی کی طرف منتقل ہو جائے گی، اگرچہ ام ولد لونڈی اپنے آقا کے مرنے کے بعد آزاد ہو جاتی ہے لیکن یہ اس وقت ہوتا ہے جب اس کا آقا مکمل آزاد ہو یا مکمل آزادی پا چکا ہو، ہاں اگر اس کا آقا کسی کا مکاتب غلام ہو اور مرتے وقت کچھ بچے چھوڑ گیا ہو جو اپنے باپ کا باقی ماندہ بدل کتابت ادا کر سکتے ہوں تو ان کے باپ کی وراثت اس کے آقا کی طرف منتقل نہیں ہوگی بلکہ انتظار کیا جائے گا، چنانچہ اگر تو یہ بچے محنت کر کے باقی ماندہ زر کتابت ادا کر دیں تو آزاد ہو جائیں گے اور اپنے باپ کا مال بھی پالیں گے اور اگر عاجز آگئے تو پھر سب کے سب اس آقا کی مکمل غلامی میں چلے جائیں گے۔","قَالَ مَالِكٌ فِي الْمُكَاتَبِ يُعْتِقُ عَبْداً لَهُ ، أَوْ يَتَصَدَّقُ بِبَعْضِ مَالِهِ وَلَمْ يَعْلَمْ بِذَلِكَ سَيِّدُهُ حَتَّى عَتَقَ الْمُكَاتَبُ . قَالَ مَالِكٌ : يَنْفُذُ ذَلِكَ عَلَيْهِ ، وَلَيْسَ لِلْمُكَاتَبِ أَنْ يَرْجِعَ فِيهِ ، فَإِنْ عَلِمَ سَيِّدُ الْمُكَاتَبِ قَبْلَ أَنْ يَعْتِقَ الْمُكَاتَبُ ، فَرَدَّ ذَلِكَ وَلَمْ يُجِزْهُ ، فَإِنَّهُ إِنْ عَتَقَ الْمُكَاتَبُ ، وَذَلِكَ فِي يَدِهِ لَمْ يَكُنْ عَلَيْهِ أَنْ يُعْتِقَ ذَلِكَ الْعَبْدَ ، وَلَا أَنْ يُخْرِجَ تِلْكَ الصَّدَقَةَ ، إِلَّا أَنْ يَفْعَلَ ذَلِكَ طَائِعاً مِنْ عِنْدِ نَفْسِهِ.","امام مالک رحمہ اللہ نے اس مکاتب غلام کے متعلق فرمایا جو اپنے کسی غلام کو آزاد کر دیتا ہے یا اپنے کچھ مال کو صدقہ کر دیتا ہے اور اس کے آقا کو اس کا پتا نہیں چلتا، یہاں تک کہ وہ مکاتب بھی آزاد ہو جاتا ہے، (بعد میں آقا کو اس کے آزاد کرنے اور صدقہ کرنے کا علم ہوتا ہے، تو امام مالک رحمہ اللہ نے فرمایا: اس (آزادی و صدقہ) کو اس (مکاتب) کی طرف سے نافذ کر دیا جائے گا اور (آزاد ہونے والے) مکاتب کے لیے جائز نہ ہوگا کہ اس میں رجوع کرے (اور یہ بہانہ بنائے کہ میرا صدقہ اور آزاد کرنا باطل تھا کیونکہ میرے آقا کو اس کا علم نہ تھا، بلکہ جو ہونا تھا وہ ہو گیا، ہاں) اگر مکاتب کے آقا کو مکاتب کے آزاد ہونے سے پہلے اس کا علم ہو گیا، پھر اس نے (آزاد شدہ غلام اور صدقہ شدہ مال) کو واپس لے لیا اور اسے جائز قرار نہ دیا (نافذ نہ کیا اور اسے باطل قرار دے کر اس غلام اور مال کو دوبارہ مکاتب غلام کے حوالے کر دیا) پھر اگر وہ مکاتب آزاد ہو جائے اور وہ (غلام اور مال) اس کے قبضے ہی میں ہو، تو اب اس پر لازم نہیں (اور اسے مجبور نہیں کیا جائے گا) کہ اس غلام کو (دوبارہ) آزاد کرے اور اسی صدقے کو (دوبارہ) نکالے، الا یہ کہ وہ اپنے دل کی خوشی سے ایسا کر لے۔ (تو درست ہے، بہر حال واجب نہیں ہے)"],"432":["§خلاصۃ الباب","اس باب میں کوئی روایت نہیں ہے، البتہ امام مالک رحمہ اللہ کے دس فتاویٰ جات مذکور ہیں۔","موت کے وقت کیا جانے والا ہر ایسا کام جس سے ورثاء کی حق تلفی ہو رہی ہو، باطل قرار پاتا ہے، ہاں میت کو اپنے ایک تہائی مال میں تصرف کا اختیار ہوتا ہے تا کہ وہ اس کی وصیت کر سکے، اسی لیے میت کے موت سے پہلے کیے ہوئے تمام صدقے اور وصیتیں صرف تہائی مال میں سے پورا کیے جانے کا حق رکھتے ہیں، اس سے زائد کالعدم اور باطل قرار پاتے ہیں، اسی طرح موت کے وقت اپنے مکاتب غلام کو آزاد کرنے کا معاملہ ہے، جسے اگر آزاد نہ کیا جائے تو اس مکاتب کو ابھی اپنی کچھ اور غلامی کا عرصہ گزارنا پڑتا اور باقی ماندہ قسطیں بھی آزاد کرنا پڑتیں جس سے ورثاء کو فائدہ ہوتا لیکن اسے قبل از موت آزاد کر دینے کی صورت میں ورثاء کی حق تلفی ہوتی ہے۔","قَالَ مَالِكٌ : إِنَّ أَحْسَنَ مَا سَمِعْتُ فِي الْمُكَاتَبِ يُعْتِقُهُ سَيِّدُهُ عِنْدَ الْمَوْتِ : أَنَّ الْمُكَاتَبَ يُقَامُ عَلَى هَيْئَتِهِ تِلْكَ ، الَّتِي لَوْ بِيعَ كَانَ ذَلِكَ الثَّمَنَ الَّذِي يَبْلُغُ ، فَإِنْ كَانَتِ الْقِيمَةُ أَقَلَّ مِمَّا بَقِيَ عَلَيْهِ مِنَ الْكِتَابَةِ وُضِعَ ذَلِكَ فِي ثُلُثِ الْمَيِّتِ ، وَلَمْ يُنْظَرْ إِلَى عَدَدِ الدَّرَاهِمِ الَّتِي بَقِيَتْ عَلَيْهِ ، وَذَلِكَ أَنَّهُ لَوْ قُتِلَ لَمْ يَغْرَمْ قَاتِلُهُ إِلَّا قِيمَتَهُ يَوْمَ قَتْلِهِ ، وَلَوْ جُرِحَ لَمْ يَغْرَمْ جَارِحُهُ إِلَّا دِيَةَ جَرْحِهِ يَوْمَ جَرَحَهُ ، وَلَا يُنْظَرُ فِي شَيْءٍ مِنْ ذَلِكَ إِلَى مَا كُوتِبَ عَلَيْهِ مِنَ الدَّنَانِيرِ وَالدَّرَاهِمِ ، لِأَنَّهُ عَبْدٌ مَا بَقِيَ عَلَيْهِ مِنْ كِتَابَتِهِ شَيْءٌ ، وَإِنْ كَانَ الَّذِي بَقِيَ عَلَيْهِ مِنْ كِتَابَتِهِ أَقَلَّ مِنْ قِيمَتِهِ لَمْ يُحْسَبْ فِي ثُلُثِ الْمَيِّتِ إِلَّا مَا بَقِيَ عَلَيْهِ مِنْ كِتَابَتِهِ ، وَذَلِكَ أَنَّهُ إِنَّمَا تَرَكَ الْمَيِّتُ لَهُ مَا بَقِيَ عَلَيْهِ مِنْ كِتَابَتِهِ ، فَصَارَتْ وَصِيَّةً أَوْصَى بِهَا.","امام مالک رحمہ اللہ نے فرمایا: یقیناً میں نے سب سے اچھی بات جو سنی ہے، اس مکاتب غلام کے متعلق جسے اس کا آقا اپنی موت کے وقت آزاد کر دیتا ہے، تو بلاشبہ اسے اس کی اس حالت (صورت اور قیمت) کے قائم مقام سمجھا جائے گا کہ اگر اسے بیچ دیا جاتا تو وہ (غلام) وہی قیمت ہوتا جس تک وہ پہنچتا، (یعنی مکاتب کی دو حالتیں اور دو قیمتیں ہوتی ہیں، ایک بدل کتابت والی اور دوسری خرید و فروخت والی۔ غلاموں کی قیمتیں، ان کے حسن، قوت، نسل، یا کسی فن میں صلاحیت و مہارت کی بنا پر کم و بیش ہوتی ہیں جبکہ بدل کتابت اس قیمت سے کم بھی ہو سکتا ہے اور زیادہ بھی، اسی لیے امام مالک رحمہ اللہ فرماتے ہیں کہ بوقت موت آزاد کیے جانے والے مکاتب غلام کو فی الفور آزاد نہیں کیا جائے گا بلکہ بازار کے ریٹ کے مطابق اس کی قیمت فروخت معلوم کی جائے گی) چنانچہ اگر مکاتب کی قیمت اس پر عائد بدل کتابت کے بقایا جات سے کم ہو تو اس (پوری قیمت) کو میت کے تہائی مال کے اندر اندر رکھ دیا جائے گا (اور دیکھا جائے گا کہ یہ کل ترکے کا کتنا حصہ بنتا ہے، اگر وہ ترکے کے تہائی حصے کے برابر یا اس سے کم ہو تو سمجھیں گے کہ میت نے اپنے مال کے تہائی حصے میں اپنا حق اور اختیار استعمال کرتے ہوئے وصیت کی ہے اور اسے اللہ کی راہ میں نکال کر آزاد کر دیا ہے، مذکورہ صورت میں مکاتب غلام کی پوری قیمت ہی تہائی مال میں شمار کی جائے گی) اور ان درہموں کی طرف نہیں دیکھا جائے گا جو (بدل کتابت میں) اس کے ذمے باقی ہیں (کیونکہ وہ زیادہ ہیں اور غلام کی آزادی تو ان درہموں سے کم مقدار میں ثابت ہو رہی ہے، تو کیا ضرورت ہے اس بات کی کہ غلام کی قیمت زیادہ شمار کریں اور ورثاء کے لیے مال میں کمی کریں) اور یہ (پوری قیمت فروخت کا اعتبار) اس وجہ سے ہے کہ اگر وہ (مکاتب غلام) قتل کر دیا جاتا تو اس کا قاتل اس کے قتل کے دن والی اس کی قیمت (بطور دیت ادا کرنے) کے سوا کچھ تاوان نہ اٹھاتا اور اگر زخمی کر دیا جاتا تو زخم لگنے کے دن اس کے زخم کی دیت کے سوا زخم لگانے والے پر کوئی چٹی نہ پڑتی اور ان میں سے کسی بھی چیز میں (یعنی قتل، زخم یا وصیت کے معاملے میں) ان دیناروں اور درہموں کی طرف نہیں دیکھا جائے گا جن پر اسے مکاتب بنایا گیا ہے، (الغرض اس کی عام قیمت فروخت ہی معتبر ہوگی نہ کہ قیمت کتابت) کیونکہ وہ بلاشبہ غلام ہی ہے جب تک کہ اس پر اس کی کتابت میں سے کچھ بھی باقی ہو۔۔۔۔۔ اور اگر وہ زر کتابت جو اس کے ذمے ہے اس کی مکمل قیمت سے کم ہو تو میت کے تہائی مال میں باقی ماندہ زر کتابت کے سوا کسی اور چیز کو شمار نہیں کیا جائے گا۔ (اس صورت میں غلام کی پوری قیمت تہائی مال سے نہیں نکالیں گے کیونکہ وہ زیادہ ہے اور غلام کی آزادی تو کم مال ہی سے ثابت ہو رہی ہے، تو کیا ضرورت ہے اس کے لیے زیادہ قیمت شمار کر کے ورثاء کے حصوں میں کمی کرنے کی؟) اور یہ بلاشبہ ایسے ہی ہے کہ جیسے میت نے اس مکاتب کے لیے اس پر عائد باقی ماندہ بدل کتابت (کا مطالبہ) چھوڑ دیا ہے اور یہ گویا ایک وصیت بن گئی ہے جو میت نے مکاتب کے لیے کی تھی۔","قَالَ مَالِكٌ : وَتَفْسِيرُ ذَلِكَ : أَنَّهُ لَوْ كَانَتْ قِيمَةُ الْمُكَاتَبِ أَلْفَ دِرْهَمٍ ، وَلَمْ يَبْقَ مِنْ كِتَابَتِهِ إِلَّا مِئَةُ دِرْهَمٍ ، فَأَوْصَى سَيِّدُهُ لَهُ بِالْمِئَةِ دِرْهَمٍ الَّتِي بَقِيَتْ عَلَيْهِ ، حُسِبَتْ لَهُ فِي ثُلُثِ سَيِّدِهِ ، فَصَارَ حُرّاً بِهَا.","امام مالک رحمہ اللہ نے فرمایا: اس کی وضاحت یوں ہے کہ اگر مکاتب غلام کی کل قیمت ایک ہزار درہم ہو اور بدل کتابت میں سے ایک سو درہم کے سوا کچھ (بھی ادائیگی) باقی نہ ہو تو (گویا) میت نے مکاتب کے لیے ایک سو درہم کی وصیت کر دی ہے جو اس پر باقی تھے، وہ میت کے تہائی مال میں اس کے لیے شمار ہوں گے، چنانچہ وہ ان کی وجہ سے آزاد شمار ہوگا۔","..... یہ وضاحت گزشتہ مسئلے کے آخری حصے کی ہے اور اس کے ابتدائی حصے کی وضاحت بھی کچھ اسی طرح ہے کہ اگر غلام کی کل قیمت ایک ہزار درہم ہو اور بدل کتابت دو ہزار درہم باقی ہو تو اب کل قیمت یعنی ایک ہزار کو مکاتب غلام کے لیے وصیت شمار کریں گے اور میت کے تہائی مال میں سے اس کا حساب لگائیں گے۔ مثلاً اگر میت کا ترکہ اس مکاتب کی قیمت سمیت تین ہزار درہم ہوں تو ایک تہائی یعنی ایک ہزار درہم وصیت میں ختم ہو جائیں گے، اسی طرح غلام آزاد ہو جائے گا اور باقی سارا ترکہ ورثاء میں تقسیم ہوگا۔۔۔۔۔ یاد رہے مذکورہ بالا مسئلے میں میت کے مکاتب غلام کو آزاد کر دینے کا تذکرہ تھا اور آگے آنے والے مسئلے میں یہ بتایا جا رہا ہے کہ میت اپنے عام غلام کو آزاد نہ کرے بلکہ مکاتب بنا کر فوت ہو تو کیا کیا جائے گا۔","قَالَ مَالِكٌ فِي رَجُلٍ كَاتَبَ عَبْدَهُ عِنْدَ مَوْتِهِ ،","امام مالک رحمہ اللہ نے اس شخص کے متعلق فرمایا جو اپنی موت إِنَّهُ يُقَوَّمُ عَبْداً، فَإِنْ كَانَ فِي ثُلُثِهِ سَعَةٌ لِثَمَنِ الْعَبْدِ جَازَ لَهُ ذَلِكَ .","کے وقت اپنے غلام کو مکاتب بنا دیتا ہے، تو بلاشبہ اس غلام کی قیمت لگائی جائے گی، پھر اگر اس میت کے تہائی مال میں غلام کی قیمت کے لیے وسعت ہو تو یہ جائز ہے (ورنہ ناجائز ہے)","قَالَ مَالِكٌ : وَتَفْسِيرُ ذَلِكَ أَنْ تَكُونَ قِيمَةُ الْعَبْدِ أَلْفَ دِينَارٍ ، فَيُكَاتِبُهُ سَيِّدُهُ عَلَى مِئَتَيْ دِينَارٍ عِنْدَ مَوْتِهِ ، فَيَكُونُ ثُلُثُ مَالِ سَيِّدِهِ أَلْفَ دِينَارٍ ، فَذَلِكَ جَائِزٌ لَهُ ، وَإِنَّمَا هِيَ وَصِيَّةٌ أَوْصَى لَهُ بِهَا فِي ثُلُثِهِ ، فَإِنْ كَانَ السَّيِّدُ قَدْ أَوْصَى لِقَوْمٍ بِوَصَايَا ، وَلَيْسَ فِي الثُّلُثِ فَضْلٌ عَنْ قِيمَةِ الْمُكَاتَبِ ، بُدِئَ بِالْمُكَاتَبِ لِأَنَّ الْكِتَابَةَ عَتَاقَةٌ ، وَالْعَتَاقَةُ تُبْدَأُ عَلَى الْوَصَايَا ، ثُمَّ تُجْعَلُ تِلْكَ الْوَصَايَا فِي كِتَابَةِ الْمُكَاتَبِ ، يَتْبَعُونَهُ بِهَا ، وَيُخَيَّرُ وَرَثَةُ الْمُوصِي ، فَإِنْ أَحَبُّوا أَنْ يُعْطُوا أَهْلَ الْوَصَايَا وَصَايَاهُمْ كَامِلَةً ، وَتَكُونَ كِتَابَةُ الْمُكَاتَبِ لَهُمْ فَذَلِكَ لَهُمْ ، وَإِنْ أَبَوْا وَأَسْلَمُوا الْمُكَاتَبَ وَمَا عَلَيْهِ إِلَى أَهْلِ الْوَصَايَا فَذَلِكَ لَهُمْ ، لِأَنَّ الثُّلُثَ صَارَ فِي الْمُكَاتَبِ ، وَلِأَنَّ كُلَّ وَصِيَّةٍ أَوْصَى بِهَا أَحَدٌ ، فَقَالَ الْوَرَثَةُ : الَّذِي أَوْصَى بِهِ صَاحِبُنَا أَكْثَرُ مِنْ ثُلُثِهِ ، وَقَدْ أَخَذَ مَا لَيْسَ لَهُ . قَالَ : فَإِنَّ وَرَثَتَهُ يُخَيَّرُونَ ، فَيُقَالُ لَهُمْ : قَدْ أَوْصَى صَاحِبُكُمْ بِمَا قَدْ عَلِمْتُمْ ، فَإِنْ أَحْبَبْتُمْ أَنْ تُنَفِّذُوا ذَلِكَ لِأَهْلِهِ عَلَى مَا أَوْصَى بِهِ الْمَيِّتُ ، وَإِلَّا فَأَسْلِمُوا","امام مالک رحمہ اللہ نے فرمایا: اور اس کی وضاحت یوں ہے کہ اس غلام کی قیمت ایک ہزار دینار ہو اور آقا اپنی موت کے وقت اسی سے دو سو دینار پر مکاتبت کر لے، پھر اس کے آقا کے ترکے کا تہائی حصہ بھی ایک ہزار دینار ہو تو یہ عمل اس کے لیے جائز ہے اور بلاشبہ یہ تو صرف اور صرف ایک وصیت ہی ہے جو میت نے اپنے تہائی مال میں غلام کے لیے کی ہے۔۔۔۔۔ پھر اگر آقا نے کچھ اور لوگوں کے لیے بھی چند وصیتیں کی ہوں، لیکن تہائی مال میں غلام کی قیمت سے زیادہ کچھ بھی نہ ہو تو (وصیت پوری کرتے وقت) مکاتب غلام ہی سے آغاز کیا جائے گا، کیونکہ مکاتبت آزادی (کا پروانہ ہے) اور آزادی (کی وصیت) تمام وصیتوں سے مقدم ہوتی ہے، چنانچہ اب سب سے پہلے غلام کو مکاتب بنائیں گے اور پھر باقی وصیتوں والوں کو محرومی سے یوں بچائیں گے کہ) پھر وہ ساری وصیتیں مکاتب کی کتابت میں ڈال دیں گے، چنانچہ (ان وصیتوں والے) لوگ ان کی ادائیگی میں مکاتب کا پیچھا کریں گے (اور اس سے مطالبہ کریں گے کہ وہ ہر وصیت والے کو اس کا حصہ ادا کرے) اور وصیت کرنے والے (فوت شدہ آقا) کے ورثاء کو اختیار دیا جائے گا، اگر وہ یہ پسند کریں کہ وصیتوں والوں کو ان کی مکمل وصیتیں ادا کر دیں اور مکاتب کی کتاب اپنے قبضے میں رکھیں تو یہ بھی ان کے لیے جائز ہے لیکن اگر وہ (ان أَهْلَ الْوَصَايَا ثُلُثَ مَالِ الْمَيِّتِ كُلِّهِ .","کے لیے کی ہوئی وصیتوں کے مطابق ادائیگی سے) انکار کر دیں اور مکاتب غلام کو اور اس کے بدل کتابت کو وصیتوں والوں کے سپرد کر دیں تو یہ بھی ان کے لیے جائز ہے، کیونکہ بلاشبہ (میت کا) تہائی مال مکاتب غلام میں (منتقل) ہو چکا ہے (تو جس جس کا تہائی مال میں حق ہے وہ اسے اس مکاتب سے نکلوا سکتا ہے) اور (ورثاء کو اختیار دینے کی) ایک وجہ یہ ہے کہ بلاشبہ ہر وصیت جو کوئی بھی شخص کرتا ہے، پھر ورثاء کہتے ہیں کہ ہمارے ساتھی (میت) نے جو کچھ وصیت کی ہے وہ اس کے تہائی مال سے زیادہ ہے اور یقیناً اس (میت) نے وہ کچھ بھی لے لیا ہے (یعنی لینا چاہا ہے) جو اس کے لیے جائز نہیں (اور اس نے تہائی مال سے تجاوز کر کے ورثاء کے حق میں تصرف کرنا چاہا) تو امام مالک رحمہ اللہ نے فرمایا: یقیناً اس کے ورثاء کو اختیار دیا جائے گا، چنانچہ ان سے کہا جائے گا کہ تمھارے صاحب نے جو وصیت کی ہے تمھیں اس کا پتا ہی ہے لہذا اگرتم یہ پسند کرو کہ تم اس (ہر ہر وصیت) کو اس کے مستحق (افراد) کے لیے (خود) نافذ کر دو، یعنی میت نے جس جس چیز کی وصیت کی ہے (اسے پورا کر دو) ورنہ تم میت کا مکمل تہائی مال وصیتوں والوں کو سپرد کر دو (وہ خود اپنے اپنے حق کے حساب سے اسے بانٹ لیں گے)۔","قَالَ : فَإِنْ أَسْلَمَ الْوَرَثَةُ الْمُكَاتَبَ إِلَى أَهْلِ الْوَصَايَا ، كَانَ لِأَهْلِ الْوَصَايَا مَا عَلَيْهِ مِنَ الْكِتَابَةِ ، فَإِنْ أَدَّى الْمُكَاتَبُ مَا عَلَيْهِ مِنَ الْكِتَابَةِ ، أَخَذُوا ذَلِكَ فِي وَصَايَاهُمْ عَلَى قَدْرِ حِصَصِهِمْ ، وَإِنْ عَجَزَ الْمُكَاتَبُ ، كَانَ عَبْداً لِأَهْلِ الْوَصَايَا ، لَا يَرْجِعُ إِلَى أَهْلِ الْمِيرَاثِ ، لِأَنَّهُمْ تَرَكُوهُ حِينَ خُيِّرُوا ، وَلِأَنَّ أَهْلَ الْوَصَايَا حِينَ أُسْلِمَ إِلَيْهِمْ ضَمِنُوهُ ، فَلَوْ مَاتَ لَمْ يَكُنْ لَهُمْ عَلَى الْوَرَثَةِ شَيْءٌ ، وَإِنْ مَاتَ الْمُكَاتَبُ قَبْلَ أَنْ يُؤَدِّيَ كِتَابَتَهُ ، وَتَرَكَ مَالاً هُوَ أَكْثَرُ مِمَّا عَلَيْهِ ، فَمَالُهُ لِأَهْلِ الْوَصَايَا ، وَإِنْ أَدَّى الْمُكَاتَبُ مَا عَلَيْهِ عَتَقَ ، وَرَجَعَ وَلَاؤُهُ إِلَى عَصَبَةِ الَّذِي عَقَدَ كِتَابَتَهُ.","امام مالک رحمہ اللہ نے فرمایا کہ اگر ورثاء اس مکاتب کو وصیتوں والوں کے سپرد کر دیں گے تو پھر وصیتوں والوں ہی کے لیے وہ زر کتابت ہوگا جو مکاتب کے ذمے ہے، چنانچہ اگر مکاتب اپنے اوپر عائد بدل کتابت ادا کر دے تو وہ اسے اپنی وصیتوں میں اپنے اپنے حصوں کے حساب سے تقسیم کر لیں گے اور اگر مکاتب غلام عاجز آ جائے گا تو وہ وصیتوں والوں کے لیے غلام بن جائے گا، وہ وراثت والوں (یعنی اپنے آقا کے ورثاء) کی طرف نہیں لوٹے گا، کیونکہ جب انھیں اختیار دیا گیا تھا تو انھوں نے اسے چھوڑ دیا تھا اور (اہل وصیت کے استحقاق کی) ایک وجہ یہ بھی ہے کہ بلاشبہ جب وہ غلام ان وصیتوں والوں کے سپرد کر دیا گیا تھا تو وہی اس کے ضامن تھے، چنانچہ اگر وہ مر جاتا تو ورثاء پر ان کے لیے کچھ حق نہ ہوتا (کیونکہ وہ تو ان کو غلام سپرد کر کے بری الذمہ ہو چکے تھے، لہذا جب غلام کی موت کی صورت میں نقصان کے حق دار یہ اہل وصیت ہیں تو غلام کے عاجز آ جانے کی صورت میں اس کے آقا بن جانے کے حق دار بھی وہی ہیں، جو نقصان کا ذمہ دار ہے وہی فائدے کا بھی حق دار ہے)۔ اگر مکاتب غلام اپنا زر کتابت ادا کرنے سے پہلے مر جائے اور اتنا مال چھوڑ کر جائے جو اس پر عائد زر کتابت سے زیادہ ہو تو اس کا یہ مال اہل وصیت ہی کے لیے ہوگا اور اگر مکاتب وہ کچھ ادا کر دے جو اس کے ذمے ہے تو وہ آزاد ہو جائے گا اور اس کی ولاء اس کے عصبہ کی طرف لوٹ جائے گی جنھوں نے اس سے کتابت کا معاملہ کیا تھا۔","قَالَ مَالِكٌ فِي الْمُكَاتَبِ يَكُونُ لِسَيِّدِهِ عَلَيْهِ عَشَرَةُ آلَافِ دِرْهَمٍ ، فَيَضَعُ عَنْهُ عِنْدَ مَوْتِهِ أَلْفَ دِرْهَمٍ . قَالَ مَالِكٌ : يُقَوَّمُ الْمُكَاتَبُ فَيُنْظَرُ كَمْ قِيمَتُهُ ، فَإِنْ كَانَتْ قِيمَتُهُ أَلْفَ دِرْهَمٍ ، فَالَّذِي وُضِعَ عَنْهُ عُشْرُ الْكِتَابَةِ ، وَذَلِكَ فِي الْقِيمَةِ مِئَةُ دِرْهَمٍ ، وَهُوَ عُشْرُ الْقِيمَةِ ، فَيُوضَعُ عَنْهُ عُشْرُ الْكِتَابَةِ ، فَيَصِيرُ ذَلِكَ إِلَى عُشْرِ الْقِيمَةِ نَقْداً ، وَإِنَّمَا ذَلِكَ كَهَيْئَتِهِ لَوْ وُضِعَ عَنْهُ جَمِيعُ مَا عَلَيْهِ ، وَلَوْ فَعَلَ ذَلِكَ لَمْ يُحْسَبْ فِي ثُلُثِ مَالِ الْمَيِّتِ ، إِلَّا قِيمَةُ الْمُكَاتَبِ أَلْفُ دِرْهَمٍ ، وَإِنْ كَانَ الَّذِي وُضِعَ عَنْهُ نِصْفُ الْكِتَابَةِ حُسِبَ فِي ثُلُثِ مَالِ الْمَيِّتِ نِصْفُ الْقِيمَةِ ، وَإِنْ كَانَ أَقَلَّ مِنْ ذَلِكَ أَوْ أَكْثَرَ ، فَهُوَ عَلَى هَذَا الْحِسَابِ.","امام مالک رحمہ اللہ نے مکاتب غلام کے متعلق فرمایا کہ آقا کے لیے اس کے ذمے دس ہزار درہم (بدل کتابت کے طور پر واجب تھے، پھر وہ اپنی موت کے وقت اس سے ایک ہزار درہم معاف کر دے (تو) امام مالک رحمہ اللہ نے فرمایا کہ اس مکاتب غلام کی قیمت لگائی جائے گی، پھر دیکھا جائے گا کہ اس کی قیمت کتنی ہے، چنانچہ اگر اس کی قیمت ایک ہزار درہم ہو تو (چونکہ وہ چیز جو اس سے معاف کی گئی تھی وہ کل زر کتابت کا دسواں حصہ تھی اور یہ (دسواں حصہ غلام کی اصل) قیمت میں سو درہم بنتا ہے (کیونکہ اس کی اصل قیمت صرف ایک ہزار درہم تھی) لہذا غلام سے زر کتابت کا دسواں حصہ معاف کیا جائے گا جو کہ نقد قیمت کے دسویں حصے کی طرف منتقل ہو جائے گا (اگر چہ زر کتابت بھی ایک قیمت ہی ہے لیکن وہ نقد اور اصل قیمت نہیں ہے اور چونکہ میت کا ہر مالی تصرف صرف تہائی مال تک محدود رہتا ہے اس لیے غلاموں کے متعلق اس کی وصیت غلام کی نقد قیمت کے لحاظ سے نافذ کی جاتی ہے)۔ اور اس کی مثال اسی طرح ہے کہ اگر اس سے وہ تمام چیز معاف کر دی جاتی جو اس پر واجب تھی، اور اگر وہ ایسا کر لے تو میت کے تہائی مال میں مکاتب غلام کی ایک ہزار درہم قیمت کے سوا کوئی چیز شمار نہ کی جائے گی، اور اگر اس سے معاف کیا ہوا حصہ زر کتابت کا نصف تھا تو میت کے تہائی مال میں قیمت کا نصف شمار کیا جائے گا اور اگر اس سے کم یا زیادہ (زر کتابت معاف ہو تو وہ اسی حساب سے (قیمت میں سے معاف) ہوگا۔","قَالَ مَالِكٌ : إِذَا وَضَعَ الرَّجُلُ عَنْ مُكَاتَبِهِ عِنْدَ مَوْتِهِ أَلْفَ دِرْهَمٍ مِنْ عَشَرَةِ آلَافِ دِرْهَمٍ ، وَلَمْ يُسَمِّ أَنَّهَا مِنْ أَوَّلِ كِتَابَتِهِ أَوْ مِنْ آخِرِهَا ،","امام مالک رحمہ اللہ نے فرمایا: جب آدمی اپنی موت کے وقت اپنے مکاتب غلام سے دس ہزار میں سے ایک ہزار درہم معاف کر دے، لیکن یہ متعین نہ کرے کہ وہ زر کتابت (کی وُضِعَ عَنْهُ مِنْ كُلِّ نَجْمٍ عُشْرُهُ .","قسطوں) کے آغاز میں سے ہوں گے یا ان کے آخر میں سے تو (چونکہ یہ معافی کل زر کتابت کا دسواں حصہ ہے اس لیے) اس مکاتب سے ہر قسط میں سے دسواں حصہ معاف کر دیا جائے گا۔","...... اکٹھی معافی کی بجائے ہر قسط میں اس معافی کا اثر ظاہر کیا جائے گا، اگر مثال کے طور پر دس ہی قسطیں ہوں اور ہر سال کی ایک ایک قسط میں ہزار ہزار درہم دیتا ہو تو ہر قسط میں سے سو سو درہم معاف کر کے ۹۰۰ درہم وصول ہوں گے، اس طرح غلام کا بھی فائدہ ہو جاتا ہے اور ورثاء کا بھی، کیونکہ انھیں مکاتب کی طرف سے ایک تسلسل کے ساتھ زر کتابت ملتا رہتا ہے۔","قَالَ مَالِكٌ : وَإِذَا وَضَعَ الرَّجُلُ عَنْ مُكَاتَبِهِ عِنْدَ مَوْتِهِ أَلْفَ دِرْهَمٍ مِنْ أَوَّلِ كِتَابَتِهِ أَوْ مِنْ آخِرِهَا ، وَكَانَ أَصْلُ الْكِتَابَةِ عَلَى ثَلَاثَةِ آلَافِ دِرْهَمٍ ، قُوِّمَ الْمُكَاتَبُ قِيمَةَ النَّقْدِ ، ثُمَّ قُسِمَتْ تِلْكَ الْقِيمَةُ فَجُعِلَ لِتِلْكَ الْأَلْفِ الَّتِي مِنْ أَوَّلِ الْكِتَابَةِ حِصَّتُهَا مِنْ تِلْكَ الْقِيمَةِ ، بِقَدْرِ قُرْبِهَا مِنَ الْأَجَلِ وَفَضْلِهَا ، ثُمَّ الْأَلْفُ الَّتِي تَلِي الْأَلْفَ الْأُولَى بِقَدْرِ فَضْلِهَا أَيْضاً ، ثُمَّ الْأَلْفُ الَّتِي تَلِيهَا بِقَدْرِ فَضْلِهَا أَيْضاً ، حَتَّى يُؤْتَى عَلَى آخِرِهَا ، تَفْضُلُ كُلُّ أَلْفٍ بِقَدْرِ مَوْضِعِهَا فِي تَعْجِيلِ الْأَجَلِ وَتَأْخِيرِهِ ، لِأَنَّ مَا اسْتَأْخَرَ مِنْ ذَلِكَ كَانَ أَقَلَّ فِي الْقِيمَةِ ، ثُمَّ يُوضَعُ فِي ثُلُثِ الْمَيِّتِ قَدْرُ مَا أَصَابَ تِلْكَ الْأَلْفَ مِنَ الْقِيمَةِ ، عَلَى تَفَاضُلِ ذَلِكَ ، إِنْ قَلَّ أَوْ كَثُرَ ، فَهُوَ عَلَى هَذَا الْحِسَابِ.","امام مالک رحمہ اللہ نے فرمایا: جب آدمی اپنی موت کے وقت مکاتب غلام کے زر کتابت کے شروع سے یا (درمیان سے یا اس کے آخر سے ایک ہزار درہم معاف کر دے اور اصل کتابت (یعنی زر کتابت کی کل مقدار) تین ہزار درہم ہو، (گویا میت نے مکاتب کا تہائی بدل کتابت معاف کر دیا ہو) تو مکاتب کی نقد قیمت لگائی جائے گی، پھر اس قیمت کو تقسیم کر دیا جائے گا، پھر وہ ہزار درہم جو زر کتابت کے شروع میں ہیں ان کے لیے ان کا حصہ، ان کے قریب اور فضیلت کے لحاظ سے قیمت میں سے نکالا جائے گا، پھر وہ ہزار درہم جو پہلے ہزار کے بعد ہیں ان کے لیے بھی ان کے (قرب اور) فضل کے لحاظ سے (قیمت کا حصہ نکالیں گے، پھر وہ ہزار درہم جو ان کے ساتھ (بعد میں) ملے ہوئے ہیں ان کے لیے بھی ان کے فضل (اور قرب) کے لحاظ سے حصہ نکالیں گے (یعنی زر کتابت کی وہ قسط جو میت کی وفات کے وقت سے جس قدر قریب ہو، اس کا مرتبہ و فضیلت اس قدر زیادہ ہے لہذا اس کی اس شان کے اعتبار سے اس قیمت میں سے حصہ دیا جائے گا، ہر قسط کے لیے غلام کی قیمت کا اتنا حصہ متعین کریں گے جتنا اس قسط کا مرتبہ ہوگا، اسی طرح حصے نکالتے چلے آئیں گے) یہاں تک کہ آخری ہزار (آخری قسط کتابت) تک پہنچ جائیں گے، ہر ہزار (ہر قسط) مدت کے جلدی ہونے یا موخر ہونے کے لحاظ سے فضیلت پاتا ہے (اور اپنے مقابلے میں زیادہ قیمت کا حق رکھتا ہے) کیونکہ بلاشبہ اس (زر کتابت) میں سے جو (جتنا) موخر ہوتا چلا جائے گا، وہ قیمت میں اتنا ہی کم (حق رکھتا) ہوگا۔ پھر میت کے تہائی مال میں اس تفاضل (کمی بیشی) والی قیمت کی اس مقدار کو رکھا جائے گا جو اس (وصیت شدہ) ہزار درہم کے حصے میں آئی تھی، اگر وہ حصہ کم ہو یا زیادہ ہو تو وہ اسی حساب سے (میت کے تہائی مال میں سے معاف) ہوگا۔","..... وصیت شدہ حصہ کتابت کے مقابلے میں جتنی قیمت آئے گی وہ معاف ہوگی بشرطیکہ ترکہ میت کے تہائی حصے میں اتنی وسعت ہو.... گزشتہ مسئلے کو سمجھنے کے لیے ایک اصول تو یہ ذہن میں رکھیے کہ مرنے والا اپنے مکاتب غلام کی کتابت میں سے جو کچھ بھی معاف کر جائے وہ معاف تو ہو جاتا ہے لیکن یہ بدل کتابت میں سے نہیں بلکہ غلام کی اصل قیمت میں سے معاف ہوتا ہے، تاکہ غلام کو بھی معافی کا فائدہ مل جائے اور ورثاء کی بھی حق تلفی نہ ہو، کیونکہ اگر میت کے قول کے مطابق بدل کتابت میں سے معافی شمار کی جائے تو وہ (زر کتابت) چونکہ غلام کی اصل قیمت سے عموماً زیادہ ہوتا ہے اس لیے غلام کو زیادہ فائدہ ملے گا اور ورثاء کی حق تلفی ہو جائے گی، اس لیے پہلے معاف شدہ بدل کتابت کا حساب لگاتے ہیں کہ وہ مکمل بدل کتابت کا کتنواں حصہ ہے، مثلاً تیسرا یا چوتھا یا دسواں وغیرہ، پھر غلام کی قیمت لگا کر اس کی کل قیمت سے اتنا حصہ معاف کر دیتے ہیں، چنانچہ اگر آقا نے مرتے وقت مکاتب کے زر کتابت کا تیسرا حصہ معاف کر دیا ہے (جیسا کہ تین ہزار میں سے ایک ہزار) تو ہم نے دیکھا کہ غلام کی اصل قیمت پندرہ سو ہے، سو ہم نے اس قیمت کا تیسرا حصہ یعنی پانچ سو روپے مکاتب سے معاف کر دیے . دوسرا اصول یہ ہے کہ غلاموں کی قیمت عموماً وقت گزرنے کے ساتھ ساتھ کم ہوتی رہتی ہے، شروع میں اس کا بھاؤ زیادہ ہوتا ہے اور بعد میں سستا ہوتا چلا جاتا ہے، اس لیے غلام کی نقد قیمت نکال کر اسے جب تین حصوں میں بانٹیں گے تو وہ حصے برابر برابر نہیں ہوں گے بلکہ پہلا حصہ ذرا زیادہ ہوگا، دوسرا اس سے کم اور تیسرا اس سے کم۔ چنانچہ مذکورہ مثال میں اگر غلام کی اصل قیمت پندرہ سو ہو تو اس کا پہلا حصہ ۶۰۰، دوسرا ۵۰۰ اور تیسرا ۴۰۰ تصور کیا جائے گا، پھر دیکھیں گے کہ اگر میت نے مکاتب غلام کے بدل کتابت سے پہلی قسط والا ہزار درہم معاف کیا تھا تو اس کے مقابلے میں آنے والا قیمت کا پہلا حصہ یعنی ۶۰۰ درہم معاف ہو جائے گا، اگر دوسری قسط معاف ہوئی تھی تو دوسرا تہائی حصہ یعنی ۵۰۰ درہم معاف ہوگا اور اگر تیسری قسط کی معافی تھی تو اس کے بالمقابل ۴۰۰ درہم معاف ہوں گے۔","قَالَ مَالِكٌ فِي رَجُلٍ أَوْصَى لِرَجُلٍ بِرُبُعِ مُكَاتَبٍ لَهُ ، وَأَعْتَقَ رُبُعَهُ فَهَلَكَ الرَّجُلُ ، ثُمَّ هَلَكَ الْمُكَاتَبُ وَتَرَكَ مَالاً كَثِيراً ، أَكْثَرَ مِمَّا","امام مالک رحمہ اللہ نے اس آدمی کے متعلق فرمایا جس نے کسی آدمی کے لیے اپنے مکاتب غلام کے ایک چوتھائی حصے کی وصیت کی اور اس کا ایک چوتھائی حصہ آزاد کر دیا، پھر وہ بَقِيَ عَلَيْهِ . قَالَ مَالِكٌ : يُعْطَى وَرَثَةُ السَّيِّدِ وَالَّذِي أَوْصَى لَهُ بِرُبُعِ الْمُكَاتَبِ مَا بَقِيَ لَهُمْ عَلَى الْمُكَاتَبِ، ثُمَّ يَقْتَسِمُونَ مَا فَضَلَ، فَيَكُونُ لِلْمُوصَى لَهُ بِرُبُعِ الْمُكَاتَبِ ثُلُثُ مَا فَضَلَ بَعْدَ أَدَاءِ الْكِتَابَةِ، وَلِوَرَثَةِ سَيِّدِهِ الثُّلُثَانِ، وَذَلِكَ أَنَّ الْمُكَاتَبَ عَبْدٌ مَا بَقِيَ عَلَيْهِ مِنْ كِتَابَتِهِ شَيْءٌ، فَإِنَّمَا يُورَثُ بِالرِّقِّ .","شخص (آقا) مر گیا، پھر مکاتب بھی مر گیا اور وہ مکاتب اتنا زیادہ مال چھوڑ گیا جو اس پر عائد باقی ماندہ (زر کتابت) سے بھی زیادہ تھا۔ تو امام مالک رحمہ اللہ نے فرمایا کہ پہلے تو آقا کے ورثاء کو اور اس شخص کو جس کے لیے میت نے مکاتب کے چوتھائی حصے کی وصیت کی تھی، (مکاتب غلام کے ترکہ میں سے) وہ رقم دی جائے گی جو ان کے لیے مکاتب کے ذمے باقی تھی (وصیت والے کے لیے چوتھائی مکاتب تھا، تو اسے بقیہ بدل کتابت کے چار حصوں میں سے ایک حصہ دیا جائے گا، ایک حصہ آزاد قرار پائے گا اور باقی دو حصے ورثاء لے لیں گے) پھر وہ سب اس مال کو تقسیم کریں گے جو (مکاتب کے ترکہ میں سے) بچ گیا ہو، چنانچہ جس کے لیے چوتھائی غلام کی وصیت کی گئی تھی اس کے لیے زر کتابت کی ادائیگی کے بعد بچے ہوئے مال میں سے ایک تہائی ہوگا اور مکاتب کے آقا کے ورثاء کے لیے دو تہائی ہوں گے اور یہ اس وجہ سے ہے کہ بے شک غلام پر جب تک اس کے بدل کتابت میں سے کچھ باقی ہو وہ غلام ہی رہے گا اور بلاشبہ غلامی ہی کے اعتبار سے اس کا وارث بنا جائے گا۔","...... اس مسئلے کی عربی عبارت کے آغاز میں ’’او‘‘ (یا) کا لفظ اور بعض نسخوں میں واؤ (اور) کے ساتھ مروی ہے اور واؤ ہی راجح ہے، کیونکہ واؤ جس کے معنی ’’اور‘‘ ہیں، ہوگی تو آگے بیان شدہ مسئلہ وراثت کی تقسیم سمجھ میں آئے گی ... کتابت کی ادائیگی کے بعد بچے ہوئے مال میں سے وصیت والے کو ایک تہائی اور ورثاء کو دو تہائی مال اس اعتبار سے ملے گا کہ مکاتب غلام کے بھی پہلے پہل چار حصے کیے جائیں گے، پھر ان میں سے ایک چوتھائی حصہ آزاد شمار ہوگا، جس کے بعد تین حصے دوسرے لوگوں کی ملکیت اور غلامی میں باقی رہ گئے، جن میں سے دو کی ملکیت ورثاء کے پاس اور ایک کی ملکیت موصی لہ (جس کے لیے وصیت کی گئی تھی) کے پاس تھی، پھر چونکہ وہ حالت غلامی ہی میں مر گیا اس لیے اس کا آزاد حصہ بھی اس کے مالکوں کی ملکیت کے حساب سے ان میں تقسیم ہو گیا۔ لہذا بقیہ ترکہ غلام کے تین حصے ہی بنیں گے جن میں سے دو تہائی ورثاء کے اور ایک تہائی موصی لہ کے لیے ہوگا... فقہی کے آخر میں امام مالک نے جو وراثت کا لفظ استعمال کیا ہے تو یہ مجاز ہے کیونکہ غلام اور آزاد کی آپس میں وراثت نہیں چلتی، لہذا (يُورَثُ) بمعنی (يُؤْخَذُ) ہے اور امام مالک رحمہ اللہ کہنا بھی یہی چاہتے ہیں کہ وہ غلامی میں مرا ہے اور غلام اور اس کا مال سب کچھ اس کے آقاؤں ہی کا مال ہوتا ہے لہذا اس کا مال اس کے مالکوں میں تقسیم ہو جائے گا، وہ حصہ جو آزاد ہو چکا تھا، وہ بھی حالت غلامی میں لوٹ آیا لہذا اس کا مال بطور وراثت نہیں بلکہ بطور ملکیت آپس میں بانٹا جائے گا۔","قَالَ مَالِكٌ فِي مُكَاتَبٍ أَعْتَقَهُ سَيِّدُهُ عِنْدَ","امام مالک رحمہ اللہ نے اس مکاتب غلام کے متعلق فرمایا جسے الْمَوْتِ . قَالَ : إِنْ لَمْ يَحْمِلْهُ ثُلُثُ الْمَيِّتِ، عَتَقَ مِنْهُ قَدْرُ مَا حَمَلَ الثُّلْثُ، وَيُوضَعُ عَنْهُ مِنَ الْكِتَابَةِ قَدْرُ ذَلِكَ، إِنْ كَانَ عَلَى الْمُكَاتَبِ خَمْسَةُ آلَافِ دِرْهَمٍ، وَكَانَتْ قِيمَتُهُ أَلْفَيْ دِرْهَمٍ نَقْداً، وَيَكُونُ ثُلُثُ الْمَيِّتِ أَلْفَ دِرْهَمٍ، عَتَقَ نِصْفُهُ، وَيُوضَعُ عَنْهُ شَطْرُ الْكِتَابَةِ .","اس کا آقا موت کے وقت آزاد کر دیتا ہے (اور یہ اصول ہے کہ بوقت موت ایسا کرنا وصیت کے زمرے میں آتا ہے اور وصیت صرف تہائی مال تک جائز ہے، لہذا مکاتب کی نقد قیمت لگا کر اسے باقی ترکہ کے ساتھ ملا کر دیکھیں گے، اگر تو وہ ترکہ کے تہائی حصے کے برابر ہوا تو آزاد ہو جائے گا، ورنہ) امام مالک رحمہ اللہ نے فرمایا کہ اگر میت کا تہائی مال اس کا جو بوجھ برداشت نہ کر سکے تو اس مکاتب سے صرف اتنا حصہ ہی آزاد ہوگا، جس کا بوجھ (میت کے مال کا تہائی حصہ اٹھا سکتا ہو اور اسی (آزاد ہونے والے) حصے کے اعتبار سے اسے زر کتابت معاف کر دیا جائے گا، (چنانچہ) اگر مکاتب کے ذمے پانچ ہزار درہم (بدل کتابت میں واجب) تھے اور (آقا کی موت کے وقت) اس کی نقد قیمت دو ہزار درہم تھی اور (اگر میت کے ترکہ کا تہائی حصہ بھی دو ہزار ہوتا تو یہ مکاتب مکمل آزاد ہو جاتا لیکن) میت کا تہائی مال ایک ہزار درہم ہو تو مکاتب کا نصف حصہ آزاد ہو جائے گا اور نصف زر کتابت اس سے معاف کر دیا جائے گا۔","..... زر کتابت پانچ ہزار درہم ہو تو اس میں سے اڑھائی ہزار درہم کی معافی ہو جائے گی۔","قَالَ مَالِكٌ فِي رَجُلٍ قَالَ فِي وَصِيَّتِهِ : غُلَامِي فُلَانٌ حُرٌّ ، وَكَاتِبُوا فُلَاناً : تُبَدَّأُ الْعَتَاقَةُ عَلَى الْكِتَابَةِ.","امام مالک رحمہ اللہ نے اس شخص کے متعلق فرمایا جس نے اپنی وصیت میں (ورثاء سے) یہ کہا کہ ’’میرا فلاں غلام آزاد ہے اور تم فلاں (غلام) کو مکاتب بنا لو‘‘ امام مالک رحمہ اللہ نے فرمایا کہ آزادی کو کتابت سے مقدم رکھا جائے گا۔","..... ان دونوں غلاموں کی نقد قیمت معلوم کی جائے گی، پھر اسے باقی ترکہ کے ساتھ ملا کر دیکھا جائے گا، چنانچہ اگر ترکہ کے تہائی حصے میں دونوں کی قیمت کی گنجائش ہو تو ایک آزاد اور ایک مکاتب بن جائے گا، اور اگر تہائی مال کی مقدار ان میں سے صرف ایک غلام کی قیمت کے برابر ہو تو پھر آزادی کی وصیت والے غلام ہی کو آزاد کیا جائے گا اور دوسرے کو مکاتب نہ بنایا جائے گا کیونکہ تمام وصیتوں میں آزادی کی وصیت مقدم ہوا کرتی ہے، اگرچہ مکاتب بنانے کا مقصد بھی آزادی ہے لیکن وہ فوری آزادی بھی نہیں اور یقینی بھی نہیں لہذا فوری اور یقینی آزادی والی وصیت پر عمل مقدم رہے گا۔"],"433":["§کتاب کا تعارف","اس کتاب میں سات ابواب اور تین روایات ہیں، جن میں سے ایک موقوف (اثر صحابی) ہے جو سنداً صحیح ہے اور دو مقطوع روایات (آثار تابعین) ہیں جن میں سے ایک صحیح اور ایک ضعیف ہے۔ نیز امام مالک رحمہ اللہ کے ۲۴ فتاویٰ جات بھی مذکور ہیں۔","..... مدبر (باء پر زبر کے ساتھ) وہ غلام ہے جس کی آزادی کو اس کا آقا اپنی موت کے ساتھ معلق کر دے اور کہے کہ ’’تو میری موت کے بعد آزاد ہے۔‘‘ دراصل ’’دبر‘‘ کے معنی پیچھے اور بعد کے بھی ہیں اور موت بھی زندگی کے بعد ہی ہوتی ہے، ایسے غلام کو مدبر، لونڈی کو مدبرہ، ان کے آقا کو مدبر (باء کے نیچے کسرہ کے ساتھ) کہتے ہیں اور اس عمل کا نام تدبیر ہے۔ اس کا یہ نام رکھنے کی ایک وجہ یہ بیان کی جاتی ہے کہ آقا اس غلام کے ابتدائی دنیوی معاملے کی تدبیر یوں کرتا ہے کہ اسے اپنا غلام بنائے رکھے اور اس سے خدمت لیتا رہے اور اس کے انتہائی معاملے کی تدبیر کرتے ہوئے اسے آزاد کر دیتا ہے، یہ مدبر بنانا بھی ایک وصیت ہی کی حیثیت رکھتا ہے، لہذا اگر میت کے تہائی مال میں اس مکمل غلام کی قیمت کے برابر گنجائش ہو تو وہ آزاد ہو جاتا ہے، ورنہ جتنی گنجائش ہو اتنا حصہ آزاد متصور ہوتا ہے۔","§خلاصۃ الباب","اس باب میں کوئی روایت نہیں ہے، البتہ امام مالک رحمہ اللہ کے چھ فتاویٰ جات مذکور ہیں۔","حَدَّثَنِي مَالِكٌ أَنَّهُ قَالَ : الْأَمْرُ عِنْدَنَا فِيمَنْ دَبَّرَ جَارِيَةً لَهُ ، فَوَلَدَتْ أَوْلَاداً بَعْدَ تَدْبِيرِهِ إِيَّاهَا ، ثُمَّ مَاتَتِ الْجَارِيَةُ قَبْلَ الَّذِي دَبَّرَهَا ، إِنَّ وَلَدَهَا بِمَنْزِلَتِهَا قَدْ ثَبَتَ لَهُمْ مِنَ الشَّرْطِ،","امام مالک رحمہ اللہ نے فرمایا: ہمارے ہاں حکم یہ ہے، اس شخص کے متعلق جو اپنی لونڈی کو مدبرہ بنا دیتا ہے، پھر اس کے اسے مدبرہ بنانے کے بعد وہ اولاد کو جنم دے دیتی ہے، پھر وہ لونڈی اپنے اس آقا سے پہلے مر جاتی ہے جس نے اسے مِثْلُ الَّذِي ثَبَتَ لَهَا، وَلَا يَضُرُّهُمْ هَلَاكُ أُمِّهِمْ، فَإِذَا مَاتَ الَّذِي كَانَ دَبَّرَهَا فَقَدْ عَتَقُوا إِنْ وَسِعَهُمُ الثُّلْثُ.","مدبرہ بنایا تھا، (تو امام مالک رحمہ اللہ نے فرمایا کہ) بلاشبہ اس کی اولاد بھی اس کے مقام پر ہوگی (اور اپنی ماں کی طرح مدبر شمار ہوگی) ان (بچوں) کے لیے بھی وہی شرط ثابت ہوگی جو اس لونڈی کے لیے ثابت ہوئی تھی اور ان کی ماں کی وفات سے ان پر کوئی ضرر نہیں آئے گا۔ چنانچہ جب وہ آقا مر جائے گا جس نے اس کو مدبرہ بنایا تھا تو یقیناً وہ (بچے) آزاد ہو جائیں گے، بشرطیکہ (میت کے) تہائی مال میں ان کی گنجائش ہو۔","..... یاد رہے کہ یہ بچوں والا معاملہ اس صورت میں ہوگا جب آقا نے اس لونڈی کی کسی اور شخص سے شادی کر رکھی ہو کیونکہ اس صورت میں بچے اپنی ماں کے آقا کے غلام شمار ہوتے تھے، رہی یہ صورت کہ وہ بچے اس لونڈی کے آقا ہی کے نطفے سے ہوں تو پھر وہ شروع ہی سے اپنے باپ کی طرح آزاد شمار ہوتے ہیں۔","وَقَالَ مَالِكٌ : كُلُّ ذَاتِ رَحِمٍ فَوَلَدُهَا بِمَنْزِلَتِهَا ، إِنْ كَانَتْ حُرَّةً فَوَلَدَتْ بَعْدَ عِتْقِهَا فَوَلَدُهَا أَحْرَارٌ ، وَإِنْ كَانَتْ مُدَبَّرَةً ، أَوْ مُكَاتَبَةً، أَوْ مُعْتَقَةً إِلَى سِنِينَ ، أَوْ مُخْدَمَةً، أَوْ بَعْضُهَا حُرًّا ، أَوْ مَرْهُونَةً ، أَوْ أُمَّ وَلَدٍ، فَوَلَدُ كُلِّ وَاحِدَةٍ مِنْهُنَّ عَلَى مِثَالِ حَالِ أُمِّهِ ، يَعْتِقُونَ بِعِتْقِهَا، وَيَرِقُّونَ بِرِقِّهَا.","امام مالک رحمہ اللہ نے فرمایا: ہر رشتہ داری والی عورت کی اولاد اس کے مرتبے میں ہوگی، اگر وہ (عورت) آزاد ہو، پھر اپنی آزادی کے بعد (بچوں کو) جنم دے تو اس کے بچے بھی آزاد ہوں گے، اور اگر وہ مدبرہ ہو یا اس سے کتابت کی گئی ہو یا کچھ سالوں کے بعد اسے آزاد کرنے کا کہا گیا ہو، یا کچھ عرصہ خدمت کے بعد اسے آزادی کا کہا گیا ہو یا کچھ حصہ آزاد (اور کچھ حصہ غلام) ہو یا وہ گروی رکھی گئی ہو، یا وہ ام ولد (اپنے آقا کے علاوہ کسی اور کے بچوں کی ماں) ہو تو ان میں سے ہر کسی کی اولاد اپنی ماں کی حالت جیسی ہوگی، اس کی آزادی کے ساتھ وہ بھی آزاد ہو جائیں گے اور اس کی غلامی کی وجہ سے وہ بھی غلام رہیں گے۔","قَالَ مَالِكٌ فِي مُدَبَّرَةٍ دُبِّرَتْ وَهِيَ حَامِلٌ وَلَمْ يَعْلَمْ سَيِّدُهَا بِحَمْلِهَا : إِنَّ وَلَدَهَا بِمَنْزِلَتِهَا ، وَإِنَّمَا ذَلِكَ بِمَنْزِلَةِ رَجُلٍ أَعْتَقَ جَارِيَةً لَهُ وَهِيَ حَامِلٌ ، وَلَمْ يَعْلَمْ بِحَمْلِهَا . قَالَ مَالِكٌ : فَالسُّنَّةُ فِيهَا أَنَّ وَلَدَهَا يَتْبَعُهَا ، وَيَعْتِقُ بِعِتْقِهَا.","امام مالک رحمہ اللہ نے اس مدبرہ لونڈی کے متعلق فرمایا جسے اس حال میں مدبرہ بنایا گیا ہو کہ وہ حاملہ تھی تو بلاشبہ اس کا بچہ بھی اسی کے مقام پر ہوگا (اور مدبر ہی شمار ہوگا) اور بلاشبہ اس کی مثال تو اس شخص کی سی ہے جو اپنی لونڈی کو اس حال میں آزاد کرتا ہے کہ وہ حاملہ ہو اور وہ اس کے حمل سے ناواقف ہو، امام مالک رحمہ اللہ نے فرمایا: اس کے متعلق سنت یہی ہے کہ یقیناً اس کا بچہ اس کے پیچھے جائے گا اور اس کی آزادی کے ساتھ ہی آزاد ہو جائے گا۔","قَالَ مَالِكٌ : وَكَذَلِكَ لَوْ أَنَّ رَجُلاً ابْتَاعَ جَارِيَةً وَهِيَ حَامِلٌ ، فَالْوَلِيدَةُ وَمَا فِي بَطْنِهَا لِمَنِ ابْتَاعَهَا ، اشْتَرَطَ ذَلِكَ الْمُبْتَاعُ أَوْ لَمْ يَشْتَرِطْهُ.","امام مالک رحمہ اللہ نے فرمایا: اور اسی طرح (یہ صورت ہے کہ) اگر کوئی شخص ایک لونڈی خریدتا ہے، درآں حالیکہ وہ حاملہ ہو تو لونڈی اور جو کچھ اس کے پیٹ میں ہوتا ہے وہ سب اس شخص کے لیے ہوتا ہے جس نے اسے خریدا ہے، خریدنے والا اس کی شرط لگائے یا نہ لگائے۔","قَالَ مَالِكٌ : وَلَا يَحِلُّ لِلْبَائِعِ أَنْ يَسْتَثْنِيَ مَا فِي بَطْنِهَا ، لِأَنَّ ذَلِكَ غَرَرٌ يَضَعُ مِنْ ثَمَنِهَا ، وَلَا يَدْرِي ، أَيَصِلُ ذَلِكَ إِلَيْهِ أَمْ لَا وَإِنَّمَا ذَلِكَ بِمَنْزِلَةِ مَا لَوْ بَاعَ جَنِيناً فِي بَطْنِ أُمِّهِ ، وَذَلِكَ لَا يَحِلُّ لَهُ لِأَنَّهُ غَرَرٌ.","امام مالک رحمہ اللہ نے فرمایا: (گزشتہ صورت میں حاملہ لونڈی کو بیچنے والے شخص کے لیے یہ جائز بھی نہیں ہے کہ وہ لونڈی کے پیٹ والی چیز کا استثناء کر لینے کی وجہ سے ظاہر ہے کہ وہ لونڈی کی قیمت میں کمی کرے گا حالانکہ وہ نہیں جانتا کہ یہ (حمل) اس تک پہنچ بھی سکے گا یا نہیں (کیونکہ ہو سکتا ہے کہ حمل ضائع ہو جائے یا عورت پہلے ہی مر جائے) اور بلاشبہ یہ تو اسی طرح ہے کہ کسی پیٹ والے بچے کو اس کی ماں کے پیٹ ہی میں بیچ دے اور یہ اس کے لیے جائز نہیں ہے کیونکہ یہ (سراسر) دھوکا ہے۔","..... کسی بھی مجہول، یعنی نا معلوم چیز، ’’معدوم یعنی غیر موجود چیز اور غیر مملوک‘‘ چیز یعنی جو اپنی ملکیت میں نہ ہو، کی خرید و فروخت بیع الغرر یعنی دھوکے کی خرید و فروخت کہلاتی ہے۔","قَالَ مَالِكٌ فِي مُكَاتَبٍ أَوْ مُدَبَّرٍ ، ابْتَاعَ أَحَدُهُمَا جَارِيَةً فَوَطِئَهَا ، فَحَمَلَتْ مِنْهُ وَوَلَدَتْ . قَالَ : وَلَدُ كُلِّ وَاحِدٍ مِنْهُمَا مِنْ جَارِيَتِهِ بِمَنْزِلَتِهِ ، يَعْتِقُونَ بِعِتْقِهِ، وَيَرِقُّونَ بِرِقِّهِ.","امام مالک رحمہ اللہ نے اس مکاتب یا مدبر غلام کے متعلق فرمایا کہ جن میں سے کوئی (اپنے لیے) ایک لونڈی خرید لیتا ہے، پھر وہ اس سے ہم بستری کرتا ہے، چنانچہ وہ اس سے حاملہ ہوتی اور بچہ جن دیتی ہے، تو فرمایا کہ بلاشبہ ان دونوں (یعنی مکاتب یا مدبر) میں سے ہر کسی کی اپنی لونڈی سے ہونے والی اولاد اسی کی طرح ہوگی (اپنے باپ کی طرح مکاتب یا مدبر شمار ہوگی)، وہ بچے اس (باپ) کی آزادی کی صورت میں آزاد ہوں گے اور اس کی غلامی کی وجہ سے غلام رہیں گے۔","قَالَ مَالِكٌ : ، فَإِذَا أُعْتِقَ هُوَ فَإِنَّمَا أُمُّ وَلَدِهِ مَالٌ مِنْ مَالِهِ يُسَلَّمُ إِلَيْهِ إِذَا أُعْتِقَ.","(امام) مالک رحمہ اللہ نے (یہ بھی) فرمایا کہ پھر جب وہ (مکاتب یا مدبر) آزاد ہوگا تو اس کی یہ ام ولد لونڈی اس کے مال میں سے ایک مال ہے لہذا جب اسے آزاد کیا جائے گا تو وہ اس کے سپرد کر دی جائے گی۔","..... مسئلے کے آخری حصے کا مطلب یہ ہے کہ اگر اس مکاتب کو زر کتابت کی ادائیگی سے قبل اور مدبر کو اس کے آقا کی موت سے قبل ہی آزادی مل جائے تو اس صورت میں بھی یہ ام ولد لونڈی اپنے آقا کے ساتھ ہی جائے گی کیونکہ یہ اسی کا مال ہے جو اس نے اپنے معاہدہ آزادی کے بعد خریدا تھا، لہذا اس مال کو اس کے آقا کا مال تصور نہ کیا جائے گا۔"],"434":["§خلاصۃ الباب","اس باب میں کوئی روایت نہیں ہے، البتہ امام مالک رحمہ اللہ کے دو فتاویٰ مذکور ہیں۔","قَالَ مَالِكٌ فِي مُدَبَّرٍ قَالَ لِسَيِّدِهِ : عَجِّلْ لِيَ الْعِتْقَ وَأُعْطِيَكَ خَمْسِينَ دِينَاراً مُنَجَّمَةً عَلَيَّ . فَقَالَ سَيِّدُهُ : نَعَمْ أَنْتَ حُرٌّ ، وَعَلَيْكَ خَمْسُونَ دِينَاراً تُؤَدَّى إِلَى كُلَّ عَامٍ عَشَرَةَ دَنَانِيرَ . فَرَضِيَ بِذَلِكَ الْعَبْدُ ، ثُمَّ هَلَكَ السَّيِّدُ بَعْدَ ذَلِكَ بِيَوْمٍ أَوْ يَوْمَيْنِ أَوْ ثَلَاثَةٍ . قَالَ مَالِكٌ : يَثْبُتُ لَهُ الْعِتْقُ، وَصَارَتِ الْخَمْسُونَ دِينَاراً دَيْناً عَلَيْهِ . وَجَازَتْ شَهَادَتُهُ ، وَثَبَتَتْ حُرْمَتُهُ وَمِيرَاثُهُ وَحُدُودُهُ ، وَلَا يَضَعُ عَنْهُ مَوْتُ سَيِّدِهِ شَيْئاً مِنْ ذَلِكَ الدَّيْنِ.","امام مالک رحمہ اللہ نے اس مدبر کے متعلق فرمایا جو اپنے آقا سے کہتا ہے کہ آپ میرے لیے آزادی کی جلدی کر دیجیے، (میں آپ کی موت کا انتظار نہیں کر سکتا) اور میں (اس کے بدلے) آپ کو پچاس دینار ادا کر دوں گا جو مجھ پر قسط وار لازم ہوں گے، تو اس کے آقا نے کہا کہ ٹھیک ہے، تم آزاد ہو اور تم پر پچاس دینار لازم ہیں، تم مجھے ہر سال دس دینار ادا کرتے رہنا، چنانچہ غلام اس پر راضی ہو گیا، پھر (ہوا یوں کہ) اس کے ایک دن یا دو دن یا تین دن بعد آقا فوت ہو گیا، تو امام مالک رحمہ اللہ نے فرمایا: اس غلام کے لیے (مدبر ہونے کی وجہ سے) آزادی ثابت ہو جائے گی اور پچاس دینار اس پر قرضے کی صورت میں (واجب الاداء) رہیں گے، اور (چونکہ اب وہ مکمل آزادی پا چکا ہے اس لیے) اس کی گواہی بھی جائز ہوگی، اس کی (آزادی والی) حرمت، وراثت اور حدود بھی ثابت ہوں گی اور (لیکن) اس کے آقا کی موت اس کے قرضے میں سے کچھ بھی ختم نہ کر سکے گی۔","..... اگر وہ جلد بازی نہ کرتا تو آقا کے مرتے ہی آزاد ہو جاتا اور اس قرضے سے بھی بچا رہتا، لیکن جب اس نے اپنی مرضی سے قرضہ اپنے سر لے لیا، حالانکہ ہر شخص کی طرح اس کے لیے بھی یہ بات واضح تھی کہ آقا کی موت کسی بھی لمحے آسکتی ہے، اس کے باوجود پچاس دینار اپنے اوپر بوجھ ڈالا تو اب یہ ادائیگی تک واجب ہی رہے گا۔","قَالَ مَالِكٌ فِي رَجُلٍ دَبَّرَ عَبْداً لَهُ ، فَمَاتَ السَّيِّدُ وَلَهُ مَالٌ حَاضِرٌ, وَمَالٌ غَائِبٌ فَلَمْ","امام مالک رحمہ اللہ نے اس شخص کے متعلق فرمایا جس نے اپنے غلام کو مدبر بنایا، پھر وہ آقا اس حال میں مرا کہ اس کا کچھ يَكُنْ فِي مَالِهِ الْحَاضِرِ مَا يَخْرُجُ فِيهِ الْمُدَبَّرُ. قَالَ: يُوقَفُ الْمُدَبَّرُ بِمَالِهِ، وَيُجْمَعُ خَرَاجُهُ حَتَّى يَتَبَيَّنَ مِنَ الْمَالِ الْغَائِبِ، فَإِنْ كَانَ فِيمَا تَرَكَ سَيِّدُهُ مِمَّا يَحْمِلُهُ الثُّلُثُ عَتَقَ بِمَالِهِ وَبِمَا جُمِعَ مِنْ خَرَاجِهِ، فَإِنْ لَمْ يَكُنْ فِيمَا تَرَكَ سَيِّدُهُ مَا يَحْمِلُهُ عَتَقَ مِنْهُ قَدْرُ الثُّلُثِ، وَتُرِكَ مَالُهُ فِي يَدَيْهِ.","مال حاضر تھا اور کچھ غائب تھا، (کاروبار میں پھنسا ہوا تھا یا کسی سے وصول ہونے والا تھا،) پھر اس کے حاضر مال میں اتنی گنجائش نہ تھی کہ اس (کے تہائی حصے) میں مدبر غلام غلامی سے نکل جاتا۔ تو امام مالک رحمہ اللہ نے فرمایا کہ مدبر کو اس کے مال سمیت روک لیا جائے گا اور (آقا کی موت کے وقت سے) اس کی (مزید) آمدنی کو جمع کیا جاتا رہے گا، یہاں تک کہ واضح ہو جائے کہ غائب مال کتنا ہے، چنانچہ اگر تو آقا کے ترکہ کے تہائی حصے میں اتنی گنجائش ہو جو اس (کی آزادی) کو برداشت کر سکے تو وہ مدبر غلام اپنے مال سمیت اور (مزید) جمع کی گئی آمدنی سمیت آزاد ہو جائے گا اور اگر آقا نے جو کچھ چھوڑا تھا اس (کے تہائی حصے) میں اس کی گنجائش نہ ہو (اور وہ تھوڑا ہو) تو ترکہ کے تہائی حصے کے بقدر غلام کو آزادی مل جائے گی اور اس کا مال اس کے قبضے ہی میں رہنے دیا جائے گا۔"],"435":["§خلاصۃ الباب","اس باب میں کوئی روایت نہیں ہے، البتہ امام مالک رحمہ اللہ کے چھ فتاویٰ جات مذکور ہیں۔","قَالَ مَالِكٌ: الْأَمْرُ الْمُجْتَمَعُ عَلَيْهِ عِنْدَنَا: أَنَّ كُلَّ عَتَاقَةٍ أَعْتَقَهَا رَجُلٌ فِي وَصِيَّةٍ أَوْصَى بِهَا، فِي صِحَّةٍ أَوْ مَرَضٍ: أَنَّهُ يَرُدُّهَا مَتَى شَاءَ، وَيُغَيِّرُهَا مَتَى شَاءَ، مَا لَمْ يَكُنْ تَدْبِيراً، فَإِذَا دَبَّرَ فَلَا سَبِيلَ لَهُ إِلَى رَدِّ مَا دَبَّرَ.","امام مالک رحمہ اللہ نے فرمایا: ہمارے ہاں اس حکم پر اجماع ہے کہ بے شک ہر وہ آزادی جس (میں کسی غلام یا لونڈی) کو آدمی وصیت کے ذریعے آزاد کرے، جس کی وصیت اس نے حالت صحت میں کی ہو یا بیماری میں، بلاشبہ وہ اسے جب چاہے (ختم کر کے) واپس (اپنی طرف) بھی لا سکتا ہے اور جب چاہے اس میں تبدیلی بھی کر سکتا ہے، جب تک کہ وہ وصیت مدبر بنانے کی نہ ہو، چنانچہ جب وہ کسی کو مدبر بنا دے تو اس کے پاس اس (غلام یا لونڈی) کو واپس لوٹانے کا کوئی اختیار نہ رہے گا۔","...... البتہ امام شافعی رحمہ اللہ اور اہل حدیث کے نزدیک بوقت مجبوری اور ضرورت مدبر کو بیچا بھی جا سکتا ہے اور یہ عمل اس کے معاہدہ تدبیر کو ختم کرنا ہی ہے، جیسا کہ آگے پانچواں باب اسی بارے میں آ رہا ہے۔","قَالَ مَالِكٌ: وَكُلُّ وَلَدٍ وَلَدَتْهُ أَمَةٌ، أَوْصَى بِعِتْقِهَا وَلَمْ تُدَبَّرْ، فَإِنَّ وَلَدَهَا لَا يَعْتِقُونَ","امام مالک رحمہ اللہ نے فرمایا: (رہا) ہر وہ بچہ جسے کسی لونڈی نے جنم دیا ہو، (تو اس میں فیصلہ یہ ہے کہ اگر) آدمی نے مَعَهَا إِذَا عَتَقَتْ، وَذَلِكَ أَنَّ سَيِّدَهَا يُغَيِّرُ وَصِيَّتَهُ إِنْ شَاءَ، وَيَرُدُّهَا مَتَى شَاءَ، وَلَمْ يَثْبُتْ لَهَا عَتَاقَةٌ، وَإِنَّمَا هِيَ بِمَنْزِلَةِ رَجُلٍ قَالَ لِجَارِيَتِهِ: إِنْ بَقِيَتْ عِنْدِي فُلَانَةٌ حَتَّى أَمُوتَ، فَهِيَ حُرَّةٌ.","اس لونڈی کی آزادی کی وصیت تو کی ہو اور (لیکن) اسے مدبرہ نہ بنایا ہو تو بلاشبہ جب وہ آزاد ہوگی تو اس کی اولاد اس کے ساتھ آزاد نہ ہوگی اور یہ اس وجہ سے ہے کہ (یہ آزادی بذریعہ وصیت ملی ہے، نہ کہ مدبر بنانے کے ذریعے) اور بلاشبہ اس لونڈی کا مالک جب چاہے اپنی وصیت میں تبدیلی کر سکتا ہے اور جب چاہے اسے فسخ بھی کر سکتا ہے اور (ان صورتوں میں) لونڈی کے لیے آزادی ثابت نہ ہوگی اور بلاشبہ یہ تو اس شخص کی طرح ہے جس نے اپنی لونڈی کے متعلق یہ کہہ دیا ہو کہ اگر وہ فلاں لونڈی میرے پاس رہی یہاں تک کہ میں مر جاؤں تو وہ آزاد ہے۔","قَالَ مَالِكٌ: فَإِنْ أَدْرَكَتْ ذَلِكَ كَانَ لَهَا ذَلِكَ، وَإِنْ شَاءَ قَبْلَ ذَلِكَ بَاعَهَا وَوَلَدَهَا لِأَنَّهُ لَمْ يُدْخِلْ وَلَدَهَا فِي شَيْءٍ مِمَّا جَعَلَ لَهَا.","امام مالک رحمہ اللہ نے فرمایا کہ اگر اس لونڈی نے اسے (یعنی اپنے آقا کی موت کو) پا لیا تو یہ آزادی اس کے لیے ثابت ہو جائے گی اور اگر آقا چاہے تو (اپنی موت سے پہلے) اسے اور اس کی اولاد کو بیچ سکتا ہے، کیونکہ اس (آقا) نے اس لونڈی کی اولاد کو کسی ایسی چیز میں شامل نہیں کیا جو اس (آقا) نے اس (لونڈی) کے لیے مقرر کی ہو۔","قَالَ: وَالْوَصِيَّةُ فِي الْعَتَاقَةِ مُخَالِفَةٌ لِلتَّدْبِيرِ، فَرَّقَ بَيْنَ ذَلِكَ مَا مَضَى مِنَ السُّنَّةِ. قَالَ: وَلَوْ كَانَتِ الْوَصِيَّةُ بِمَنْزِلَةِ التَّدْبِيرِ، كَانَ كُلُّ مُوصٍ لَا يَقْدِرُ عَلَى تَغْيِيرِ وَصِيَّتِهِ، وَمَا ذُكِرَ فِيهَا مِنَ الْعَتَاقَةِ، وَكَانَ قَدْ حَبَسَ عَلَيْهِ مِنْ مَالِهِ مَا لَا يَسْتَطِيعُ أَنْ يَنْتَفِعَ بِهِ.","امام مالک رحمہ اللہ نے فرمایا: بہر حال ’’عتق‘‘ (یعنی محض لفظ آزادی کے ساتھ کی جانے) والی وصیت ’’مدبر بنانے‘‘ (کے عمل یا وصیت) کے برعکس اور مخالف ہے۔ ان دونوں میں اس طریقے اور سنت نے بھی فرق کر دیا ہے جو (پہلے سے) جاری ہو چکی ہے۔ امام مالک رحمہ اللہ نے فرمایا کہ اگر (ہر) وصیت مدبر بنانے کی طرح ہوتی تو ہر وصیت کرنے والا اپنی (کسی بھی) وصیت میں تبدیلی پر قدرت نہ رکھتا اور اس آزادی میں بھی (تبدیلی نہ کر سکتا) جس کا پیچھے ذکر کیا گیا ہے اور (اگر ہر وصیت مدبر بنانے کی طرح ناقابل تغییر ہو جائے، تو پھر یہ ایسے ہی ہے کہ گویا) آدمی نے اپنے پاس ایسا مال روک رکھا ہے جس سے نفع اٹھانے کی وہ گنجائش نہیں رکھتا۔","...... الغرض عام وصیتوں میں اور مدبر بنانے میں فرق ہے۔ لفظ ’’عتق‘‘ اور ’’عتاقہ‘‘ بھی آزادی کے لیے مستعمل ہیں لیکن ان کو مدبر بنانے پر قیاس نہیں کیا جا سکتا، بلکہ ان کے ساتھ کی جانے والی وصیت عام وصیتوں جیسی ہے جن میں رد و بدل جائز ہے۔","قَالَ مَالِكٌ فِي رَجُلٍ دَبَّرَ رَقِيقاً لَهُ جَمِيعاً فِي صِحَّتِهِ، وَلَيْسَ لَهُ مَالٌ غَيْرُهُمْ. قَالَ: إِنْ كَانَ دَبَّرَ بَعْضَهُمْ قَبْلَ بَعْضٍ، بُدِءَ بِالْأَوَّلِ فَالْأَوَّلِ، حَتَّى يَبْلُغَ الثُّلُثَ، وَإِنْ كَانَ دَبَّرَهُمْ جَمِيعاً فِي مَرَضِهِ، فَقَالَ فُلَانٌ حُرٌّ، وَفُلَانٌ حُرٌّ، وَفُلَانٌ حُرٌّ، فِي كَلَامٍ وَاحِدٍ، إِنْ حَدَثَ بِي فِي مَرَضِي هَذَا حَدَثُ مَوْتٍ، أَوْ دَبَّرَهُمْ جَمِيعاً فِي كَلِمَةٍ وَاحِدَةٍ، تَحَاصَوْا فِي الثُّلُثِ، وَلَمْ يُبَدَّأْ أَحَدٌ مِنْهُمْ قَبْلَ صَاحِبِهِ، وَإِنَّمَا هِيَ وَصِيَّةٌ، وَإِنَّمَا لَهُمُ الثُّلُثُ، يُقْسَمُ بَيْنَهُمْ بِالْحِصَصِ، ثُمَّ يَعْتِقُ مِنْهُمُ الثُّلُثُ بَالِغاً مَا بَلَغَ. قَالَ: وَلَا يُبْدَأُ أَحَدٌ مِنْهُمْ إِذَا كَانَ ذَلِكَ كُلُّهُ فِي مَرَضِهِ.","امام مالک رحمہ اللہ نے اس شخص کے متعلق فرمایا جس نے اپنے تمام غلاموں کو حالت صحت میں مدبر بنا ڈالا اور اس کے پاس ان کے سوا کوئی مال بھی نہ تھا، تو فرمایا: اگر تو اس نے ان میں سے کچھ (غلاموں) کو بعض (غلاموں) سے پہلے مدبر بنایا تھا تو پھر (ترتیب سے) پہلے کے ساتھ، پھر اس کے بعد والے کے ساتھ آغاز کیا جائے گا، (جن کو پہلے مدبر بنایا تھا وہ ترتیب وار آزاد ہوتے چلے جائیں گے) یہاں تک کہ یہ تہائی حصے تک پہنچ جائے۔ (پھر اتنے غلام ترتیب سے آزاد ہوں گے جن کے لیے میت کے ترکہ کے تہائی حصے میں گنجائش ہو) اور اگر اس نے ان تمام کو اپنی بیماری میں مدبر بنایا تھا اور اس نے ایک ہی کلام میں یہ کہہ دیا تھا کہ فلاں غلام بھی آزاد ہے اور فلاں بھی آزاد ہے۔ بشرطیکہ میری اس بیماری میں میرے ساتھ موت کا حادثہ پیش آ جائے، یا اس نے ان تمام کو ایک ہی لفظ (جملے) کے ساتھ مدبر بنا دیا ہو، تو وہ (تمام غلام) تہائی مال میں برابر کے حصہ دار ہوں گے اور ان میں سے کسی کو بھی اس کے کسی دوسرے ساتھی سے مقدم نہ کیا جائے گا اور بلاشبہ یہ بھی صرف اور صرف ایک وصیت ہی ہے (اور وصیت میت کے تہائی مال میں سے ادا کی جاتی ہے، اس سے زیادہ سے نہیں) اور یقیناً ان غلاموں کے لیے اب یہی تہائی مال ہے جو ان کے درمیان حصوں میں تقسیم ہوگا، پھر ان میں سے ایک تہائی حصہ آزاد ہو جائے گا، خواہ وہ (قیمت کے لحاظ سے) کسی بھی مقدار کو پہنچنے والا ہو۔ امام مالک رحمہ اللہ نے فرمایا: اور (جس طرح ایک لفظ میں سب کو مدبر بنانے کی صورت میں سب غلام تہائی مال میں شریک ہوتے ہیں اسی طرح اس صورت میں بھی) ان میں سے کسی کو اس کے ساتھی سے مقدم نہ کیا جائے گا جس وقت کہ یہ تمام (کو مدبر بنانا) اس کی بیماری میں ہوا ہو۔","...... مقصد یہ ہے کہ میت کے ترکہ کے تہائی حصے کے برابر جتنے مدبر غلاموں کی گنجائش ہوگی وہ آزاد ہو جائیں گے، اس سے زیادہ نہیں، چنانچہ اگر تو ثلث (تہائی مال) اتنا زیادہ ہو کہ سب غلاموں کی قیمت سے بھی زیادہ ہو تو سب آزاد ہوں گے، لیکن اگر اس ثلث مال کی مقدار کم ہو اور غلاموں کی قیمت اس سے زیادہ ہو تو پھر دیکھیں گے، اگر وہ حالت صحت میں یکے بعد دیگرے ترتیب سے مدبر بنائے گئے تھے تو ثلث مال کی گنجائش کے مطابق پہلے مدبر بنائے جانے والے آزاد ہوں گے لیکن اگر انھیں اکٹھے یا حالت مرض میں مدبر بنایا گیا ہو تو پھر کسی غلام کو دوسروں پر فوقیت نہ ہوگی، سب تہائی مال میں برابر کے حصہ دار ہوں گے اور حصہ دار ہونے کا مطلب یہ ہے کہ ان سب میں قرعہ ڈالا جائے گا، جن کے نام نکل آئے وہ آزاد ہوں گے جس کا طریقہ کار یہ ہے کہ تمام غلاموں کے تین گروپ بنا کر قرعہ نکالیں گے جس گروپ کا نام نکل آیا وہ آزاد اور باقی غلام ہی رہیں گے۔","قَالَ مَالِكٌ فِي رَجُلٍ دَبَّرَ غُلَاماً لَهُ، فَهَلَكَ السَّيِّدُ، وَلَا مَالَ لَهُ إِلَّا الْعَبْدُ الْمُدَبَّرُ، وَلِلْعَبْدِ مَالٌ. قَالَ: يُعْتَقُ ثُلُثُ الْمُدَبَّرِ وَيُوقَفُ مَالُهُ بِيَدَيْهِ.","امام مالک رحمہ اللہ نے اس شخص کے متعلق فرمایا جس نے اپنے غلام کو مدبر بنا دیا ہو، پھر آقا اس حال میں فوت ہوا ہو کہ اس کے پاس اس مدبر غلام کے سوا کوئی مال نہ تھا اور (البتہ) اس مدبر غلام کے پاس مال تھا تو امام مالک رحمہ اللہ نے فرمایا: مدبر کا تیسرا حصہ آزاد ہو جائے گا اور اس کا مال اس کے قبضے میں رہنے دیا جائے گا۔","...... مدبر کو چونکہ پروانہ آزادی مل چکا تھا اس لیے اس کا مال آقا کا مال شمار نہیں ہوگا اور اسی کے قبضے میں رہے گا، البتہ آقا کا مجموعی ترکہ چونکہ یہی مدبر غلام ہے اس لیے اس کا صرف تہائی حصہ آزاد ہوگا، باقی نہیں۔","قَالَ مَالِكٌ فِي مُدَبَّرٍ كَاتَبَهُ سَيِّدُهُ فَمَاتَ السَّيِّدُ وَلَمْ يَتْرُكْ مَالاً غَيْرَهُ. قَالَ مَالِكٌ: يُعْتَقُ مِنْهُ ثُلُثُهُ، وَيُوضَعُ عَنْهُ ثُلُثُ كِتَابَتِهِ، وَيَكُونُ عَلَيْهِ ثُلُثَاهَا.","امام مالک رحمہ اللہ نے اس مدبر غلام کے متعلق فرمایا جسے (بعد میں) اس کے آقا نے مکاتب (بھی) بنا دیا ہو، پھر آقا مر گیا اور اس نے اس (غلام) کے سوا کوئی مال بھی نہ چھوڑا، تو امام مالک رحمہ اللہ نے فرمایا: اس غلام میں سے تہائی حصہ تو آزاد ہو جائے گا اور اس سے زر کتابت کا تہائی حصہ معاف کر دیا جائے گا (کیونکہ غلام کا وہ تہائی حصہ آزادی پا چکا ہے) اور بدل کتابت کا دو تہائی حصہ اس کے ذمے (واجب الادا) رہے گا۔","قَالَ مَالِكٌ فِي رَجُلٍ أَعْتَقَ نِصْفَ عَبْدٍ لَهُ وَهُوَ مَرِيضٌ، فَبَتَّ عِتْقَ نِصْفِهِ، أَوْ بَتَّ عِتْقَهُ كُلَّهُ، وَقَدْ كَانَ دَبَّرَ عَبْداً لَهُ آخَرَ قَبْلَ ذَلِكَ. قَالَ: يُبْدَأُ بِالْمُدَبَّرِ قَبْلَ الَّذِي أَعْتَقَهُ وَهُوَ مَرِيضٌ، وَذَلِكَ أَنَّهُ لَيْسَ لِلرَّجُلِ أَنْ يَرُدَّ مَا دَبَّرَ، وَلَا أَنْ يَتَعَقَّبَهُ بِأَمْرٍ يَرُدُّهُ بِهِ، فَإِذَا عَتَقَ الْمُدَبَّرُ فَلْيَكُنْ مَا بَقِيَ مِنَ الثُّلُثِ فِي الَّذِي أَعْتَقَ شَطْرَهُ، حَتَّى يَسْتَتِمَّ بِهِ عِتْقُهُ كُلُّهُ فِي","امام مالک رحمہ اللہ نے اس شخص کے متعلق فرمایا جس نے اپنے غلام کا نصف حصہ اس حال میں آزاد کیا کہ وہ مریض تھا، پھر اس نے اس کی مکمل آزادی کو پختہ کر دیا (اور قطعی فیصلہ کر لیا) یا اس نے اس کے نصف حصے کی آزادی ہی کو پختہ کیا اس حال میں کہ وہ اس سے پہلے کسی اور غلام کو مدبر بنا چکا تھا، (پھر وہ آقا مر گیا، چنانچہ اگر تو اس کے ترکہ کے تہائی حصے میں دونوں کی آزادی کی گنجائش ہو تو ٹھیک ہے، ورنہ) امام مالک رحمہ اللہ نے فرمایا کہ مدبر غلام کو اس شخص ثُلُثِ مَالِ الْمَيِّتِ، فَإِنْ لَمْ يَبْلُغْ ذَلِكَ فَضْلَ الثُّلُثِ، عَتَقَ مِنْهُ مَا بَلَغَ فَضْلَ الثُّلُثِ بَعْدَ عِتْقِ الْمُدَبَّرِ الْأَوَّلِ.","(دوسرے غلام) سے مقدم رکھا جائے گا جسے اس آقا نے (بغیر مدبر بنائے) اس حال میں آزاد کیا تھا کہ وہ آقا بیمار تھا، اور یہ (فیصلہ) اس وجہ سے ہے کہ بلاشبہ آدمی کے لیے جائز نہیں کہ وہ اس غلام کو (اپنی ملکیت کی طرف) واپس لوٹائے جسے مدبر بنا دیا تھا، اور نہ یہ جائز ہے کہ اس (مدبر بنانے) کے بعد (یا اپنے دنیا سے جانے کے بعد کے لیے) کوئی ایسا حکم دے جائے جس کے ذریعے وہ اس مدبر کو واپس لوٹا لے، (لہذا مدبر کو پہلے ہی آزاد کر دیا جائے گا) چنانچہ جب مدبر آزاد ہو جائے گا تو پھر تہائی مال میں سے جو کچھ بچا ہوا ہو وہ اس (دوسرے) غلام میں استعمال ہوگا جس کا میت نے نصف حصہ آزاد کیا تھا، (اور اگر گنجائش ہوئی تو نصف سے زیادہ آزادی بھی مل سکتی ہے) یہاں تک کہ اس کی آزادی میت کے تہائی مال کے اندر اندر مکمل ہو جائے، (لیکن) اگر (مدبر غلام کی آزادی کے بعد) تہائی حصے میں سے بچا ہوا مال اس (دوسرے غلام کی مکمل آزادی) کو نہ پہنچتا ہو تو اس غلام میں سے صرف اتنا حصہ آزاد ہوگا جس تک پہلے مدبر غلام کی آزادی کے بعد بقیہ تہائی مال پہنچ سکے۔"]})